insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('baunhof-fluaridsduaf', 'Baunhof Fluaridsduaf', '', '', '', '', 'Bahnhof Floridsdorf', '[{"kategorie": "allg.", "text": "\"wichtiger Verkehrsknotenpunkt im Norden Wiens, im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Der Bahnhof Floridsdorf befindet sich im Zentrum des gleichnamigen Bezirks. Er liegt an der [[Prager]] Straße, in der Nähe der [[Floridsdorfer]] Hauptstraße, und ist ein wichtiges Tor für den Verkehr in den Norden Wiens. Die Lage am Übergang zwischen dem städtischen Gebiet und den ländlicheren Regionen nördlich der Donau macht den Bahnhof zu einem zentralen Knotenpunkt im Wiener und niederösterreichischen Verkehrsnetz"}, {"kategorie": "", "text": "Der Bahnhof Floridsdorf hat eine lange Geschichte, die mit dem Wachstum Wiens und der Eingemeindung von Floridsdorf 1904 in die Stadt Wien eng verbunden ist. Ursprünglich war der Bahnhof ein Endpunkt für Züge, die die nordöstlichen Regionen Österreichs mit Wien verbanden. Mit dem Ausbau des Wiener Nahverkehrs und der Errichtung der U-Bahn-Linie U6 erlebte der Bahnhof in den letzten Jahrzehnten eine enorme Aufwertung"}, {"kategorie": "", "text": "Im Zuge der Modernisierungen wurde der Bahnhof umfassend renoviert, um den gestiegenen Anforderungen als Verkehrsknotenpunkt gerecht zu werden. Sowohl die hervorragende Anbindung an den öffentlichen Nahverkehr als auch die moderne Infrastruktur machen ihn zu einem der wichtigsten Bahnhöfe der Stadt."}]'::jsonb, ''),
  ('praga-schdrossn', 'Praga Schdrossn', '', '', '', '', 'Prager Straße', '[{"kategorie": "allg.", "text": "\"eine der Hauptverkehrsstraßen in Wien, die durch den 21. Wiener Gemeindebezirk ([[Floridsdorf]]) verläuft\""}, {"kategorie": "", "text": "Sie beginnt im Süden an der [[Floridsdorfer]] Brücke, die den Bezirk Floridsdorf mit dem 20. Bezirk ([[Brigittenau]]) verbindet. Von dort verläuft sie in nordwestlicher Richtung und führt durch mehrere Wohn- und Gewerbegebiete Floridsdorfs, bevor sie in den Bezirk [[Strebersdorf]] übergeht und schließlich an der Stadtgrenze zu Niederösterreich endet"}, {"kategorie": "", "text": "Die Prager Straße hat eine lange Geschichte, die eng mit der Erschließung des nördlichen Wiener Umlands und dem Ausbau der Verkehrsverbindungen in Richtung Niederösterreich verbunden ist. Historisch diente sie als Verbindung zwischen Wien und Prag (daher der Name), da sie entlang des historischen Handelsweges in diese Richtung verläuft. Im Laufe der Zeit wurde sie immer stärker als Verkehrsstraße ausgebaut und spielt heute eine zentrale Rolle im Wiener Straßennetz."}]'::jsonb, ''),
  ('fluaridsduafa-hauptschdrossn', 'Fluaridsduafa Hauptschdrossn', '', '', '', '', 'Floridsdorfer Hauptstraße', '[{"kategorie": "allg.", "text": "\"zentrale Einkaufs- und Verkehrsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Sie verläuft durch das historische Zentrum des Bezirks und stellt eine der wichtigsten innerstädtischen Straßen in diesem Teil Wiens dar"}, {"kategorie": "", "text": "Die Floridsdorfer Hauptstraße verbindet den [[Bahnhof]] Floridsdorf, einen bedeutenden Verkehrsknotenpunkt, mit anderen Teilen des Bezirks und dient sowohl dem Autoverkehr als auch als Fußgängerzone für Shopping und Freizeitaktivitäten"}, {"kategorie": "", "text": "Die Floridsdorfer Hauptstraße war historisch gesehen eine der Hauptverbindungsstraßen des Bezirks und hat sich mit dem Wachstum von Floridsdorf zu einer wichtigen Einkaufsstraße entwickelt. Durch ihre teilweise Fußgängerzone und die Lage im Herzen des Bezirks ist sie ein beliebter Treffpunkt für Bewohner und Besucher."}]'::jsonb, ''),
  ('pfoakiachn-fraunz-von-assisi', 'Pfoakiachn Fraunz von Assisi', '', '', '', '', 'Pfarrkirche Franz von Assisi', '[{"kategorie": "allg.", "text": "\"beeindruckende römisch-katholische Kirche im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), direkt am [[Mexikoplatz]] nahe der [[Donau]] (auch bekannt als \"Mexikokirche\")\""}, {"kategorie": "", "text": "Sie ist eines der markantesten Bauwerke im Nordosten Wiens und ein bedeutendes Wahrzeichen der Stadt"}, {"kategorie": "", "text": "Die Pfarrkirche Franz von Assisi wurde zwischen 1898 und 1910 erbaut. Anlass für den Bau war das 50-jährige Regierungsjubiläum von Kaiser Franz Joseph I., weshalb die Kirche ursprünglich auch als \"Kaiserjubiläumskirche\" bezeichnet wurde"}, {"kategorie": "", "text": "Der Architekt der Kirche war Victor Luntz, der sich beim Design an romanischen Baustilen orientierte und die Kirche mit mächtigen Rundbögen, Türmen und einem [[Rosettenfenster]] gestaltete. Die Kirche zeichnet sich durch ihre massiven, roten Türme und ihre großen, ornamentierten Fassaden aus. Die Hauptkuppel der Kirche erhebt sich zentral über dem Bauwerk und wird von vier kleineren Türmen flankiert. Besonders auffällig sind der Hauptturm und die zwei flankierenden Türme, die der Kirche ihre markante Silhouette verleihen"}, {"kategorie": "", "text": "Die Kirche ist dem heiligen Franz von Assisi gewidmet, einem der bekanntesten Heiligen der römisch-katholischen Kirche und Gründer des Franziskanerordens. Franz von Assisi, der im 12. und 13. Jahrhundert lebte, ist bekannt für seine Bescheidenheit, seine Liebe zur Natur und seine Hingabe an die Armen und Bedürftigen"}, {"kategorie": "", "text": "Die Pfarrkirche Franz von Assisi ist eine aktive Pfarrkirche. Neben den regulären Messen finden in der Kirche auch Hochzeiten, Taufen und andere kirchliche Zeremonien statt. Die Kirche bietet zudem Raum für gemeindliche Aktivitäten, darunter soziale und karitative Projekte, die besonders in einem multikulturellen Bezirk wie der Leopoldstadt von großer Bedeutung sind."}]'::jsonb, ''),
  ('franziskana-plotz', 'Franziskana Plotz', '', '', '', '', 'Franziskaner Platz', '[{"kategorie": "allg.", "text": "\"kleiner, aber historisch und architektonisch bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Der Franziskanerplatz liegt in einem der ältesten Stadtteile Wiens, wenige Minuten vom [[Stephansplatz]] entfernt. Den Namen hat er von der [[Franziskanerkirche]], die dort Anfang des 17. Jahrhunderts im Renaissancestil mit gotischen Elementen erbaut wurde. Und er hat, wie es sich für einen ordentlichen Platz gehört, auch einen Brunnen, den à„Moses-Brunnen“"}, {"kategorie": "", "text": "Der Franziskanerplatz strahlt mit seiner barocken Architektur und der Lage abseits des Trubels eine besondere Atmosphäre aus und ist ein beliebter Ort für Einheimische und Touristen, die Wiens kulturelles und historisches Erbe erleben möchten."}]'::jsonb, ''),
  ('franziskana-kiachn', 'Franziskana Kiachn', '', '', '', '', 'Franziskaner Kirche', '[{"kategorie": "allg.", "text": "\"bedeutende römisch-katholische Kirche im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die direkt am [[Franziskanerplatz]] liegt (offizieller Name: \"Kirche St. Hieronymus\")\""}, {"kategorie": "", "text": "Sie gehört zum angrenzenden Franziskanerkloster und ist sowohl architektonisch als auch historisch ein bemerkenswertes Bauwerk in Wien. Die Kirche ist dem heiligen Hieronymus gewidmet und vereint architektonische Stilelemente der Renaissance und des Barocks"}, {"kategorie": "", "text": "Die Franziskanerkirche wurde zwischen 1603 und 1611 im Stil der Renaissance erbaut, was sie zu einem der wenigen Gebäude dieser Epoche in Wien macht. Der Entwurf stammte von italienischen Baumeistern, was sich in der klaren und strengen Fassade der Kirche widerspiegelt. Die Kirche wurde als Teil des Franziskanerklosters errichtet, das von Franziskanermönchen bewohnt und genutzt wird"}, {"kategorie": "", "text": "Die Außenfassade der Franziskanerkirche ist schlicht und eher untypisch für barocke Kirchen, was auf die Renaissance-Bauweise zurückzuführen ist. Über dem Hauptportal befindet sich eine Statue des heiligen Hieronymus, der Namenspatron der Kirche, sowie das Wappen des Franziskanerordens. Die Fassade ist im Vergleich zu anderen Wiener Kirchen eher zurückhaltend und klassisch gestaltet, was der Kirche jedoch einen besonderen historischen Charme verleiht"}, {"kategorie": "", "text": "Die Franziskanerkirche beherbergt mehrere bedeutende Kunstwerke, die vor allem dem Barock zuzuordnen sind. Besonders hervorzuheben ist der Hochaltar, der 1707 von Andrea Pozzo geschaffen wurde. Dieser ist ein Meisterwerk barocker Kunst und zeigt eine dramatische Darstellung des heiligen Hieronymus, der auf dem Altar in einer spirituellen Szene dargestellt wird"}, {"kategorie": "", "text": "Die Kirche verfügt auch über ein bedeutendes Chorgestühl sowie eine imposante Orgel aus dem Jahr 1642, die von Johann Wöckerl gebaut wurde und eine der ältesten erhaltenen Orgeln Wiens ist"}, {"kategorie": "", "text": "Während der Türkenbelagerungen Wiens im 17. Jahrhundert diente die Kirche auch als Zufluchtsort und spielte in der religiösen und sozialen Versorgung der Stadt eine wesentliche Rolle"}, {"kategorie": "", "text": "Neben der Kirche befindet sich das Franziskanerkloster, das ebenfalls eine lange Geschichte hat. Es wurde zur gleichen Zeit wie die Kirche gegründet und ist bis heute ein aktives Kloster des Franziskanerordens."}]'::jsonb, ''),
  ('s-baun', 'S-Baun', '', '', '', '', 'S-Bahn', '[{"kategorie": "wörtlich, Abkürzung für \"Schnellbahn\"", "text": "= \"städtisches Nahverkehrssystem der Stadt Wien und ihres Umlandes, das insbesondere die Stadt mit den umliegenden Regionen in Niederösterreich und dem Burgenland verbindet (oft auch als [[S-Bahn Wien]] bezeichnet)"}, {"kategorie": "", "text": "Die Wiener Schnellbahn ist ein elektrisch betriebenes Eisenbahnsystem, das auf bestehenden Eisenbahnstrecken der ÖBB (Österreichische Bundesbahnen) verkehrt. Sie stellt schnelle Verbindungen zwischen den außerhalb gelegenen Bezirken und Vororten Wiens und der Innenstadt her und ist damit ein zentrales Verkehrsmittel für Pendler, die täglich in die Stadt und wieder hinausfahren. Neben der Erschließung des Wiener Stadtgebiets verbindet die Schnellbahn Wien mit Städten und Gemeinden in den angrenzenden Bundesländern"}, {"kategorie": "", "text": "Das Schnellbahnnetz in Wien besteht aus mehreren S-Bahn-Linien, die mit einem „S“ und einer Nummer gekennzeichnet sind, z. B. S1, S2, S3 und S7. Jede dieser Linien bedient unterschiedliche Strecken"}, {"kategorie": "", "text": "Das Wiener S-Bahn-Netz wurde 1954 ins Leben gerufen, um Wien besser mit den Vororten zu verknüpfen. Ursprünglich hieß das System „Schnellbahn“, der Begriff „S-Bahn“ wurde später verbreiteter"}, {"kategorie": "", "text": "Die S45 ist eine Querverbindung innerhalb der Stadt, auch als [[Vorortelinie]] bekannt, die ohne das Stadtzentrum zu berühren mehrere wichtige Außenbezirke miteinander verbindet."}]'::jsonb, ''),
  ('liisinga-plotz', 'Liisinga Plotz', '', '', '', '', 'Liesinger Platz', '[{"kategorie": "allg.", "text": "\"zentraler öffentlicher Platz im 23. Wiener Gemeindebezirk ([[Liesing]]), der das historische und verkehrstechnische Zentrum des Bezirks bildet\""}, {"kategorie": "", "text": "Der Liesinger Platz befindet sich nahe dem [[Bahnhof]] Liesing, der einer der wichtigsten Bahnhöfe des Bezirks ist. Der Platz liegt zentral im Bezirk und ist von Wohngebieten, Einkaufsmöglichkeiten und öffentlichen Einrichtungen umgeben. Durch seine Lage im Bezirkszentrum ist er ein wichtiges Ziel für die Bewohner Liesings und angrenzender Gebiete"}, {"kategorie": "", "text": "Der Liesinger Platz hat sich im Laufe der Zeit von einem lokalen Marktplatz zu einem wichtigen städtischen Zentrum entwickelt. Ursprünglich war Liesing eine eigenständige Gemeinde, die erst 1938 im Rahmen der Eingemeindung zu Wien dem 23. Bezirk angeschlossen wurde. Der Liesinger Platz war schon damals ein zentraler Treffpunkt und hat durch den Ausbau des Verkehrsnetzes und die wachsende Bedeutung Liesings als Wohn- und Pendlerbezirk an Relevanz gewonnen."}]'::jsonb, ''),
  ('pfoakiachn-hetznduaf', 'Pfoakiachn Hetznduaf', '', '', '', '', 'Pfarrkirche Hetzendorf', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 12. Wiener Gemeindebezirk ([[Meidling]]), im Stadtteil [[Hetzendorf]] am [[Marschallplatz]] 6 (auch bekannt als \"Pfarrkirche Maria, Königin des hochheiligen Rosenkranzes\" bzw. \"Rosenkranzkirche\")"}, {"kategorie": "", "text": "Sie wurde im 20. Jahrhundert erbaut und trägt den offiziellen Namen \"Maria Rosenkranzkönigin\""}, {"kategorie": "", "text": "Sie wurde zwischen 1908 und 1909 nach Plänen der Architekten Hubert Gangl und Eugen Felgel errichtet und ist ein bedeutendes Beispiel für den Stil der Kirchenarchitektur dieser Zeit"}, {"kategorie": "", "text": "Die Innenausstattung stammt von dem bekannten Holzbildhauer Franz Zelezny, der unter anderem den Altar und andere sakrale Möbelstücke der Kirche schuf. Zeleznys Arbeit zeichnet sich durch detaillierte Schnitzereien und künstlerische Verzierungen aus, die der schlichten Architektur eine warme, handwerkliche Note verleihen"}, {"kategorie": "", "text": "Die Rosenkranzkirche liegt an der [[Hetzendorfer]] Straße im südwestlichen Teil Wiens. Sie ist im neugotischen Stil erbaut und befindet sich in unmittelbarer Nähe des [[Schlosses]] Hetzendorf."}]'::jsonb, ''),
  ('hetznduafa-schdrossn', 'Hetznduafa Schdrossn', '', '', '', '', 'Hetzendorfer Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 12. Wiener Gemeindebezirk ([[Meidling]]), die durch den Stadtteil [[Hetzendorf]] verläuft und das Viertel mit anderen Teilen Wiens verbindet"}, {"kategorie": "", "text": "Die Hetzendorfer Straße hat ihren Namen von dem Stadtteil Hetzendorf, durch den sie verläuft. Ursprünglich war Hetzendorf ein kleines Dorf, das erst im 19. Jahrhundert in die Stadt Wien eingemeindet wurde. Mit dem Wachstum Wiens und der zunehmenden Bebauung des 12. Bezirks wurde die Hetzendorfer Straße zu einer wichtigen Verkehrsverbindung"}, {"kategorie": "", "text": "Eines der markantesten Bauwerke entlang der Straße ist das barocke [[Schloss]] Hetzendorf, das heute die renommierte Modeschule Hetzendorf beherbergt. Das Schloss und der umliegende Park sind ein bedeutendes kulturelles und historisches Highlight des Stadtteils"}]'::jsonb, ''),
  ('baunhof-hetznduaf', 'Baunhof Hetznduaf', '', '', '', '', 'Bahnhof Hetzendorf', '[{"kategorie": "allg.", "text": "wichtiger Regional- und [[S-Bahnhof]] im 12. Wiener Gemeindebezirk ([[Meidling]]), im Stadtteil [[Hetzendorf]]"}, {"kategorie": "", "text": "Der Bahnhof Hetzendorf liegt an der [[Hetzendorfer]] Straße und ist gut in das öffentliche Verkehrsnetz eingebunden. Er befindet sich in der Nähe des [[Schlosses]] Hetzendorf und der [[Rosenkranzkirche]] und ist von Wohngebieten und kleineren Gewerbegebieten umgeben"}, {"kategorie": "", "text": "Der Bahnhof Hetzendorf wurde im Zuge des Ausbaus der Südbahnstrecke errichtet, die eine der ältesten und wichtigsten Bahnlinien Österreichs ist. Ursprünglich diente der Bahnhof hauptsächlich dem ländlichen Verkehr, doch mit dem Wachstum der Stadt Wien und der Eingemeindung der Vororte, einschließlich Hetzendorfs, wurde der Bahnhof zunehmend in das städtische Nahverkehrsnetz integriert."}]'::jsonb, ''),
  ('baunhof-geaschdhof', 'Baunhof Geaschdhof', '', '', '', '', 'Bahnhof Gersthof', '[{"kategorie": "allg.", "text": "\"wichtiger Verkehrsknotenpunkt im 18. Wiener Gemeindebezirk ([[Währing]])\""}, {"kategorie": "", "text": "Er liegt an der [[Vorortelinie]] (S45), einer [[S-Bahn-Strecke]], die den nördlichen und westlichen Teil Wiens verbindet, und spielt eine bedeutende Rolle für den öffentlichen Nahverkehr im Bezirk"}, {"kategorie": "", "text": "Der Bahnhof Gersthof wurde im Zuge des Ausbaus der Vorortelinie eröffnet, die ursprünglich als Verbindung der Wiener Vororte diente. Die Strecke und der Bahnhof wurden im späten 19. Jahrhundert errichtet, als Wien seine Stadterweiterungen vorantrieb. Nach dem Zweiten Weltkrieg wurde der Betrieb auf der Vorortelinie vorübergehend eingestellt, jedoch in den 1980er Jahren wieder aufgenommen und modernisiert"}, {"kategorie": "", "text": "Das [[Gersthofer]] Platzl, in unmittelbarer Nähe des Bahnhofs, ist ein beliebter Treffpunkt mit vielen Einkaufsmöglichkeiten. Zudem befinden sich in der Umgebung auch einige Schulen und Bildungseinrichtungen, was den Bahnhof für Schüler und Lehrer zu einem wichtigen Verkehrsknoten macht."}]'::jsonb, ''),
  ('geaschdhofa-platzl', 'Geaschdhofa Platzl', '', '', '', '', 'Gersthofer Platzl', '[{"kategorie": "allg.", "text": "kleiner, aber zentraler Platz im 18. Wiener Gemeindebezirk ([[Währing]]), genauer gesagt im Stadtteil [[Gersthof]]"}, {"kategorie": "", "text": "Das Gersthofer Platzl ist Teil des historischen Stadtteils Gersthof, der bereits im Mittelalter existierte. Mit der Eingemeindung nach Wien im Jahr 1892 entwickelte sich der Stadtteil zu einem wichtigen Wohngebiet im 18. Bezirk. Das Platzl selbst hat sich im Laufe des 20. Jahrhunderts zu einem belebten Zentrum für den lokalen Handel und öffentlichen Verkehr entwickelt"}, {"kategorie": "", "text": "Mit zahlreichen Geschäften, Cafés und Dienstleistungsbetrieben ist das Gersthofer Platzl ein lebendiger und unverzichtbarer Teil des Stadtteils Gersthof."}]'::jsonb, ''),
  ('geaschdhofa-schdrossn', 'Geaschdhofa Schdrossn', '', '', '', '', 'Gersthofer Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsader im 18. Wiener Gemeindebezirk ([[Währing]])\""}, {"kategorie": "", "text": "Sie verläuft durch den Stadtteil [[Gersthof]], von dem sie ihren Namen hat, und erstreckt sich vom Wiener Vorort Gersthof bis hin zur Grenze des 19. Bezirks ([[Döbling]])"}, {"kategorie": "", "text": "Entlang der Gersthofer Straße finden sich zahlreiche Geschäfte, Restaurants und Dienstleistungsbetriebe, die diese Straße zu einem wirtschaftlichen Zentrum von Währing machen. Besonders rund um den [[Bahnhof]] Gersthof, der an der [[Vorortelinie]] S45 liegt, ist die Gersthofer Straße äußerst belebt"}, {"kategorie": "", "text": "Die Bebauung entlang der Gersthofer Straße ist vielfältig, mit einem Mix aus Gründerzeitbauten, modernen Wohnhäusern und Geschäftsgebäuden. Besonders im Bereich um den Bahnhof Gersthof und die angrenzenden Straßen ist die Architektur vom klassischen Wiener Stil des 19. Jahrhunderts geprägt. Diese älteren Gebäude mit hohen Decken und verzierten Fassaden bieten einen historischen Charme und verleihen der Gegend eine gehobene Atmosphäre."}]'::jsonb, ''),
  ('pfoakiachn-sankt-severin', 'Pfoakiachn Sankt Severin', '', '', '', '', 'Pfarrkirche Sankt Severin', '[{"kategorie": "allg.", "text": "römisch-katholische Kirche im 18. Wiener Gemeindebezirk ([[Währing]])"}, {"kategorie": "", "text": "Sie befindet sich in der Vinzenzgasse und ist dem heiligen Severin von Noricum geweiht, einem der wichtigsten Missionare und Kirchenväter der Spätantike in der Region des heutigen Österreichs"}, {"kategorie": "", "text": "Die Pfarrkirche Sankt Severin wurde in der Mitte des 20. Jahrhunderts erbaut und ist im Vergleich zu vielen älteren Kirchen Wiens relativ modern und schlicht\""}, {"kategorie": "", "text": "Der Namensgeber der Kirche, Severin von Noricum, war ein bedeutender Kirchenvater und Missionar im 5. Jahrhundert. Er gilt als Schutzpatron von Österreich und hat im Gebiet des ehemaligen römischen Noricum, dem heutigen Österreich, gewirkt. Er setzte sich besonders für die Armen und Schwachen ein und gründete mehrere christliche Gemeinden entlang der Donau"}, {"kategorie": "", "text": "Die Kirche, auch als Lazaristenkirche bezeichnet, wurde zwischen 1876 und 1878 von den Lazaristen, einem katholischen Orden, erbaut und 1939 zur Pfarre erhoben. Besonders bemerkenswert ist die Kriegergedächtniskapelle, die in den 1950er Jahren hinzugefügt wurde."}]'::jsonb, ''),
  ('waehringa-park', 'Währinga Park', '', '', '', '', 'Währinger Park', '[{"kategorie": "allg.", "text": "\"bedeutende Grünfläche im 18. Wiener Gemeindebezirk ([[Währing]]), die zu den beliebten Naherholungsgebieten der Bezirksbewohner zählt\""}, {"kategorie": "", "text": "Der Park liegt in der Nähe der [[Währinger]] Straße und erstreckt sich über ein Areal von rund 5,5 Hektar"}, {"kategorie": "", "text": "Der Währinger Park befindet sich auf dem ehemaligen Gelände des Währinger Ortsfriedhofs, der bis 1923 in Gebrauch war. Teile des Friedhofs, darunter mehrere Gräber von prominenten Persönlichkeiten wie dem Komponisten Franz Schubert und dem Dichter Johann Baptist Mayrhofer, wurden an andere Standorte verlegt, um Platz für den heutigen Park zu schaffen. Einige historische Grabdenkmäler sind jedoch erhalten geblieben und erinnern an die frühere Nutzung des Geländes"}, {"kategorie": "", "text": "Der Park wurde ab 1923 als öffentlicher Park angelegt und gehört zu den ältesten und traditionsreichsten Parks in Währing. Der historische Charme des Parks wird durch die alten Bäume und die verbleibenden Denkmäler unterstrichen."}]'::jsonb, ''),
  ('arthaber-plotz', 'Arthaber Plotz', '', '', '', '', 'Arthaber Platz', '[{"kategorie": "allg.", "text": "markanter Platz im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Er befindet sich im südlichen Teil Wiens und trägt den Namen von Franz Arthaber (1795–1867), einem wohlhabenden Industriellen und Kunstmäzen, der sich durch seine sozialen und wirtschaftlichen Beiträge in Wien auszeichnete"}, {"kategorie": "", "text": "Er dient als sozialer Treffpunkt in einem dicht besiedelten Wohngebiet und zeichnet sich durch seine gute Verkehrsanbindung sowie seine zentrale Lage im Bezirk aus"}, {"kategorie": "", "text": "Der Platz ist von Wohnhäusern, Geschäften und öffentlichen Einrichtungen umgeben und bietet durch seine ruhige Gestaltung eine Oase im städtischen Leben."}]'::jsonb, ''),
  ('doeblinga-hauptschdrossn', 'Döblinga Hauptschdrossn', '', '', '', '', 'Döblinger Hauptstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Geschäftsstraße im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Sie erstreckt sich durch das Zentrum des Bezirks und spielt eine zentrale Rolle für den lokalen Verkehr und das Alltagsleben in Döbling"}, {"kategorie": "hist.", "text": "Die Döblinger Hauptstraße folgt dem Verlauf einer römischen Limesstraße, wobei sich im Bereich zwischen Hofzeile und Wertheimsteinpark eine slawische Siedlung befand, die urkundlich 1114 als Teopilic bzw. Toplice genannt wurde"}, {"kategorie": "", "text": "Entlang der Döblinger Hauptstraße findet sich eine Mischung aus [[Gründerzeitgebäuden]], modernen Wohnhäusern und Geschäftsgebäuden. Viele der historischen Gebäude stammen aus der Zeit der Stadterweiterung Wiens im späten 19. Jahrhundert und prägen das Stadtbild mit ihren verzierten Fassaden. Im nördlichen Teil der Straße, in Richtung [[Grinzing]], werden die Gebäude zunehmend moderner, und es gibt auch einige Einfamilienhäuser und Villen"}, {"kategorie": "", "text": "Die Döblinger Hauptstraße verbindet die urbaneren und ländlicheren Teile von Döbling miteinander und dient als Rückgrat des öffentlichen Lebens in diesem Teil Wiens. Besonders im Bereich des [[Nussdorfer]] Platzes und der [[Heiligenstädter]] Straße bildet die Döblinger Hauptstraße einen wichtigen Verkehrsknotenpunkt."}]'::jsonb, ''),
  ('peeda-joadan-schrossn', 'Peeda-Joadan-Schrossn', '', '', '', '', 'Peter-Jordan-Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsader, die durch den 18. Bezirk ([[Währing]]) und den 19. Bezirk ([[Döbling]]) verläuft"}, {"kategorie": "", "text": "Sie verläuft durch eine grüne und gehobene Wohngegend, die von Villen, modernen Wohnhäusern sowie zahlreichen Forschungs- und Bildungseinrichtungen geprägt ist\""}, {"kategorie": "", "text": "Die Straße ist nach dem Agrarwissenschaftler Peter Jordan (1751–1827) benannt, der als einer der Pioniere in der landwirtschaftlichen Forschung und Lehre in Österreich gilt"}, {"kategorie": "", "text": "Die Bebauung entlang der Peter-Jordan-Straße ist vielfältig. Im südlichen Teil der Straße dominieren Bildungseinrichtungen und Forschungszentren ([[BOKU]] Wien), während weiter nördlich exklusive Wohnhäuser, Villen und große Grünflächen die Szenerie prägen. Die Lage in der Nähe des [[Wienerwaldes]] und des [[Türkenschanzparks]] macht diesen Bereich zu einem begehrten Wohnort."}]'::jsonb, ''),
  ('boku-wiin', 'BOKU Wiin', '', '', '', '', 'BOKU Wien', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Universität für Bodenkultur Wien\" = \"renommierte Universität in Österreich, die sich auf Wissenschaft und Forschung im Bereich der Lebens- und Umweltressourcen spezialisiert hat\""}, {"kategorie": "", "text": "Gegründet wurde sie im Jahr 1872 und gehört heute zu den führenden Universitäten für nachhaltige Entwicklung und Agrarwissenschaften in Europa"}, {"kategorie": "", "text": "Die „k.k. Hochschule für Bodencultur“ wurde 1872 mit Rektorats- und Dekanatsverfassung in Wien gegründet, die Eröffnung fand am 15. Oktober 1872 statt. Zu ihren Gründungsvätern gehörte unter anderem Joseph Roman Lorenz (österreichischer Gymnasiallehrer, Volkswirt und Naturforscher)"}, {"kategorie": "", "text": "Die BOKU Wien hat mehrere Standorte in Wien, darunter den Türkenschanz-Campus (Hauptstandort), nahe dem [[Türkenschanzpark]], und den [[Muthgasse-Campus]] in Döbling, wo sich mehrere Forschungsinstitute befinden."}]'::jsonb, ''),
  ('kronan-zeitung', 'Kronan Zeitung', '', '', '', '', 'Kronen Zeitung', '[{"kategorie": "wörtlich, kurz", "text": "\"Krone\" = \"eine der meistgelesenen Tageszeitungen in Österreich\""}, {"kategorie": "", "text": "Sie wurde im Jahr 1900 gegründet und ist seitdem eine zentrale Stimme in der österreichischen Medienlandschaft. Die Zeitung ist bekannt für ihren populistischen Stil und ihre einfache Sprache, was sie für ein breites Publikum zugänglich macht"}, {"kategorie": "", "text": "Mit einer Auflage von mehreren Hunderttausend Exemplaren und einer noch größeren Online-Leserschaft ist die Krone eine der einflussreichsten Zeitungen Österreichs. Sie hat maßgeblichen Einfluss auf die öffentliche Meinung und wird oft als „Stimme des Volkes“ bezeichnet"}, {"kategorie": "", "text": "Die Eigentümerstruktur der Zeitung ist aufgeteilt zwischen der Familie Dichand, den Gründern der Zeitung, und der Funke Mediengruppe, einem deutschen Medienkonzern. Diese Aufteilung hat in der Vergangenheit oft zu Spannungen geführt, vor allem hinsichtlich der redaktionellen Kontrolle"}, {"kategorie": "", "text": "Trotz starker Kritik bleibt sie ein wichtiger Akteur in der österreichischen Medienlandschaft, der die öffentliche Meinung maßgeblich beeinflusst."}]'::jsonb, ''),
  ('da-standard', 'Da Standard', '', '', '', '', 'Der Standard', '[{"kategorie": "allg.", "text": "\"renommierte österreichische Tageszeitung, die im Jahr 1988 von Oscar Bronner gegründet wurde\""}, {"kategorie": "", "text": "Sie gilt als eine der führenden qualitätsorientierten Zeitungen in Österreich und ist bekannt für ihre unabhängige und linksliberale Berichterstattung"}, {"kategorie": "", "text": "Die Online-Version der Zeitung, derStandard.at, gehört zu den meistgelesenen Nachrichtenportalen in Österreich. Es bietet nicht nur Nachrichten und Analysen, sondern auch eine Plattform für Leserkommentare und Diskussionen. Der Online-Auftritt ist bekannt für seine sehr aktive Lesercommunity und die umfangreiche Beteiligung an Debatten"}, {"kategorie": "", "text": "Die Redaktion ist bekannt für gründliche Recherche, analytische Tiefe und oft kritische Berichterstattung. Darüber hinaus ist der Standard als eine der wenigen Zeitungen in Österreich bekannt, die immer wieder auf gesellschaftspolitische Themen wie Menschenrechte, Umweltfragen und soziale Gerechtigkeit hinweist"}, {"kategorie": "", "text": "Der Hauptanteilseigner von \"Der Standard\" ist die Bronner Online AG, die auch die Mehrheitsbeteiligung an der \"Standard Verlagsgesellschaft m.b.H.\" hält. Die Bronner-Familie, insbesondere Oscar Bronner, hat maßgeblichen Einfluss auf die Ausrichtung der Zeitung."}]'::jsonb, ''),
  ('de-presse', 'De Presse', '', '', '', '', 'Die Presse', '[{"kategorie": "allg.", "text": "\"eine der renommiertesten österreichischen Tageszeitungen mit Sitz in Wien\""}, {"kategorie": "", "text": "Sie wurde bereits 1848 gegründet und gehört zu den ältesten und traditionsreichsten Zeitungen des Landes"}, {"kategorie": "", "text": "Die Presse ist bekannt für ihre konservative und wirtschaftsliberale Ausrichtung und wird als Qualitätszeitung geschätzt, die sich auf fundierte Berichterstattung und analytischen Journalismus konzentriert"}, {"kategorie": "", "text": "Die Presse wurde im Jahr 1848 während der Märzrevolution von den Journalisten August Zang und Michael Etienne gegründet. Während ihrer langen Geschichte hat sich die Zeitung stets durch ihre Unabhängigkeit und ihr Eintreten für bürgerliche und liberale Werte ausgezeichnet"}, {"kategorie": "", "text": "Die Presse gilt traditionell als wirtschaftsliberal und konservativ. Sie positioniert sich im politischen Spektrum eher rechts der Mitte und setzt sich für Marktwirtschaft, bürgerliche Freiheiten und liberale Demokratie ein"}, {"kategorie": "", "text": "Die Presse gehört zur Styria Media Group AG, einem der größten Medienkonzerne in Österreich, der auch andere bedeutende Zeitungen wie die Kleine Zeitung besitzt. Die Styria Media Group hat ihren Ursprung in der Steiermark und ist mehrheitlich im Besitz der katholischen Kirche, übt jedoch redaktionell keine direkte Einflussnahme auf die Zeitung aus."}]'::jsonb, ''),
  ('wiina-planetarium', 'Wiina Planetarium', '', '', '', '', 'Wiener Planetarium', '[{"kategorie": "allg.", "text": "\"bedeutendes Bildungs- und Freizeitzentrum für Astronomie und Raumfahrt in Wien\""}, {"kategorie": "", "text": "Es befindet sich im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), direkt im [[Prater]], einem der größten Parks der Stadt"}, {"kategorie": "", "text": "Das Planetarium dient sowohl der wissenschaftlichen Bildung als auch der Unterhaltung, indem es Besuchern einen Einblick in die Welt der Astronomie und des Kosmos bietet"}, {"kategorie": "", "text": "Das Wiener Planetarium wurde 1964 eröffnet und war damals mit einem modernen Projektionssystem ausgestattet, das es ermöglichte, den Sternenhimmel detailgetreu darzustellen. Seitdem wurde es mehrmals modernisiert, zuletzt im Jahr 2002, als ein neues, digitales Projektionstheater eingebaut wurde, das hochauflösende Darstellungen von Himmelsphänomenen ermöglicht"}, {"kategorie": "", "text": "Besucher können sich virtuelle Reisen durch das Universum, Planetensysteme, Sternbilder und kosmische Ereignisse ansehen. Besonders beliebt sind die speziellen Programme für Kinder, bei denen auf einfache und unterhaltsame Weise astronomische Themen erklärt werden."}]'::jsonb, ''),
  ('hoche-warte', 'Hoche Warte', '', '', '', '', 'Hohe Warte', '[{"kategorie": "allg.", "text": "gehobene Wohn- und Erholungsgegend  im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Die Hohe Warte erstreckt sich auf einem Hügel nördlich des Stadtzentrums Wiens, in der Nähe der Stadtteile [[Grinzing]] und [[Heiligenstadt]]. Die Gegend ist geprägt von prachtvollen Villen, die hauptsächlich im späten 19. und frühen 20. Jahrhundert errichtet wurden. Diese Villen sind oft von großzügigen Gärten umgeben und bieten einen exklusiven Wohnraum für wohlhabende Bewohner"}, {"kategorie": "", "text": "In der Umgebung befinden sich historische Gebäude wie die Zentralanstalt für Meteorologie und Geodynamik, die 1851 gegründet wurde und heute als wichtiger meteorologischer und geophysikalischer Forschungsstandort gilt"}, {"kategorie": "", "text": "Die Wetterstation Hohe Warte ist eine der bekanntesten Einrichtungen auf der Hohen Warte. Diese Station spielt eine zentrale Rolle in der Wetterbeobachtung und -vorhersage für Österreich. Sie wurde im Jahr 1872 eröffnet und gehört zur Zentralanstalt für Meteorologie und Geodynamik (ZAMG)"}, {"kategorie": "", "text": "Die Hohe Warte ist auch als Heimat des Stadions Hohe Warte bekannt. Das Stadion wurde 1921 eröffnet und war eines der größten und modernsten Stadien seiner Zeit in Europa. Heute ist es die Heimstätte des Fußballvereins First Vienna FC 1894, des ältesten Fußballvereins Österreichs."}]'::jsonb, ''),
  ('doeblinga-friidhof', 'Döblinga Friidhof', '', '', '', '', 'Döblinger Friedhof', '[{"kategorie": "", "text": "Er liegt am Rande des [[Wienerwaldes]] und gehört zu den ältesten und bekanntesten Friedhöfen in Wien"}, {"kategorie": "", "text": "Der Friedhof liegt an der Hartäckerstraße und umfasst eine Fläche von etwa 8,5 Hektar:  4. Der Döblinger Friedhof wurde 1880 eröffnet, als der alte Friedhof in [[Grinzing]], der heutige [[Grinzinger]] Friedhof, für die wachsende Bevölkerung nicht mehr ausreichend war"}, {"kategorie": "", "text": "Viele bekannte österreichische Persönlichkeiten sind auf dem Döblinger Friedhof bestattet, darunter Ernst Haeusserman (Burgtheaterdirektor) und Ferdinand von Saar (österreichischer Schriftsteller und Dramatiker). Zudem beherbergt der Friedhof zahlreiche kunstvolle Grabmäler, die die Architektur und Kultur der vergangenen Jahrhunderte widerspiegeln."}]'::jsonb, ''),
  ('kioksbuaga-friidhof', 'Kioksbuaga Friidhof', '', '', '', '', 'Kalksburger Friedhof', '[{"kategorie": "", "text": "Er befindet sich im historischen Stadtteil [[Kalksburg]], einer ländlichen Gegend, die von der Nähe zum [[Wienerwald]] geprägt ist"}, {"kategorie": "", "text": "Der Kalksburger Friedhof wurde im 19. Jahrhundert angelegt, ist traditionell gestaltet und beherbergt eine Mischung aus Familiengräbern, Ehrengräbern und modernen Grabstätten"}, {"kategorie": "", "text": "Das prominenteste Grab ist wohl jenes von Hugo von Hofmannsthal, der als einer der bedeutendsten Vertreter der Wiener Moderne gilt und durch Werke wie \"Jedermann\" und seine Zusammenarbeit mit Richard Strauss berühmt wurde"}, {"kategorie": "", "text": "Er verstarb im Jahr 1929 und ist gemeinsam mit seiner Familie auf dem kleinen und ruhigen Kalksburger Friedhof begraben. Dieser friedliche Ort spiegelt die Besinnlichkeit und den Rückzug wider, die Hofmannsthal auch in vielen seiner Werke thematisierte."}]'::jsonb, ''),
  ('hiitzinga-friidhof', 'Hiitzinga Friidhof', '', '', '', '', 'Hietzinger Friedhof', '[{"kategorie": "", "text": "Er liegt in einem der nobelsten Bezirke der Stadt und ist bekannt für seine gepflegte Anlage sowie die vielen prominenten Persönlichkeiten, die dort ihre letzte Ruhestätte gefunden haben"}, {"kategorie": "", "text": "Der Hietzinger Friedhof befindet sich an der [[Maxingstraße]], nahe dem [[Schlosspark]] Schönbrunn"}, {"kategorie": "", "text": "Er wurde im Jahr 1787 eröffnet und gehört damit zu den ältesten Friedhöfen Wiens"}, {"kategorie": "", "text": "Zahlreiche bekannte Künstler, Politiker und Wissenschaftler sind auf dem Hietzinger Friedhof beigesetzt, darunter: Gustav Klimt (weltberühmter Maler des Jugendstils), Otto Wagner (Architekt und Stadtplaner, der das Wiener Stadtbild maßgeblich prägte), Franz Grillparzer (bedeutender österreichischer Schriftsteller und Dramatiker), Heinrich \"Heinz\" Conrads (Schauspieler, Fernseh- und Radiomoderator) sowie Gerhard Hannapi (Fußballer)"}, {"kategorie": "", "text": "Der Friedhof verfügt über eine Jugendstil-Aufbahrungshalle, die den architektonischen Stil der damaligen Zeit widerspiegelt. Er ist in verschiedene Sektionen unterteilt, wobei es neben den traditionellen Gräbern auch Urnengräber gibt. Viele der Grabmäler sind kunstvoll gestaltet und zeugen von der Geschichte und dem Reichtum der hier beigesetzten Persönlichkeiten."}]'::jsonb, ''),
  ('atzgasduafa-friidhof', 'Atzgasduafa Friidhof', '', '', '', '', 'Atzgersdorfer Friedhof', '[{"kategorie": "", "text": "Der Atzgersdorfer Friedhof befindet sich an der Friedhofstraße und zählt mit einer Fläche von etwa 5 Hektar zu den mittelgroßen Friedhöfen in Wien"}, {"kategorie": "", "text": "Die Ursprünge des Atzgersdorfer Friedhofs gehen auf die Entwicklung des Stadtteils [[Atzgersdorf]] zurück, der im Zuge der Industrialisierung im 19. Jahrhundert wuchs. Er ist heute eine zentrale Begräbnisstätte für die Einwohner des 23. Bezirks"}, {"kategorie": "", "text": "Die architektonische Gestaltung der Gräber reicht von schlichten Familiengrabstätten bis zu aufwendig gestalteten Grabmälern, die teilweise mit künstlerischen Elementen versehen sind."}]'::jsonb, ''),
  ('grinzinga-friidhof', 'Grinzinga Friidhof', '', '', '', '', 'Grinzinger Friedhof', '[{"kategorie": "", "text": "Er gehört zu den ältesten und geschichtsträchtigsten Friedhöfen Wiens und ist insbesondere als letzte Ruhestätte vieler berühmter Persönlichkeiten bekannt. Mit seiner malerischen Lage am Rande der [[Wiener]] Weinberge zieht der Friedhof sowohl Angehörige als auch Interessierte und Touristen an"}, {"kategorie": "", "text": "Der Grinzinger Friedhof liegt am Grinzinger Steig in der Nähe der historischen [[Heurigengegend]] von Grinzing und des [[Wienerwalds]]. Der Friedhof ist vergleichsweise klein, aber sehr gepflegt und liegt idyllisch in B10158einer grünen und ruhigen Umgebung"}, {"kategorie": "", "text": "Der Grinzinger Friedhof ist die letzte Ruhestätte zahlreicher bedeutender Persönlichkeiten, darunter Gustav Mahler (weltberühmter Komponist und Dirigent), Alma Mahler-Werfel (Komponistin und Witwe von Gustav Mahler), Heinrich von Ferstel (Heinrich von Ferstel (bedeutender österreichischer Architekt des 19. Jahrhunderts, der maßgeblich zur Gestaltung Wiens im Historismus beigetragen hat), Leopold Kupelwieser (Wiener Maler der Biedermeierzeit) und Heimito von Doderer (einflussreicher Schriftsteller des 20. Jahrhunderts) und Richard Lugner (Bauunternehmer und Wiener Original). Zusätzlich gibt es Gräber von Mitgliedern prominenter Wiener Familien, die seit Generationen in Grinzing ansässig sind."}]'::jsonb, ''),
  ('wiina-weinbeag', 'Wiina Weinbeag', '', '', '', '', 'Wiener Weinberge', '[{"kategorie": "allg.", "text": "bedeutende und landschaftlich reizvolle Region, die sich entlang der Hänge des Wienerwaldes erstreckt, hauptsächlich im 19. Bezirk ([[Döbling]]), in den Stadtteilen [[Grinzing]], [[Nussdorf]], [[Neustift]] am Walde, [[Sievering]], aber auch in Teilen von Floridsdorf ([[Stammerdorf]]) und Liesing ([[Mauer]])"}, {"kategorie": "", "text": "Sie sind Teil des weltberühmten [[Wiener]] Weinbaus und ein wichtiger Bestandteil der Stadtlandschaft, die einzigartige [[Weinkultur]] und Naherholung miteinander verbindet"}, {"kategorie": "", "text": "Die Weingärten befinden sich auf sonnigen Hängen, die günstige Bedingungen für den Weinbau bieten"}, {"kategorie": "", "text": "Der Weinbau hat in Wien eine lange Tradition, die bis in die Römerzeit zurückreicht. Bereits im Mittelalter war der Wiener Wein ein wichtiger Wirtschaftsfaktor, und die Stadt Wien ist bis heute eine der wenigen Weltstädte, in denen Weinbau innerhalb der Stadtgrenzen betrieben wird. Der Wiener Weinbau hat sich in den letzten Jahrhunderten ständig weiterentwickelt und ist heute ein Symbol für die kulinarische Tradition der Stadt"}, {"kategorie": "", "text": "Die Wiener Weinberge sind bekannt für ihre Vielfalt an Rebsorten, sowohl für weiße als auch für rote Weine. Die wichtigste weiße Rebsorte ist der [[Grüne]] Veltliner, gefolgt von [[Riesling]] und [[Welschriesling]]. Besonders berühmt ist Wien für den [[Wiener]] Gemischten Satz, eine traditionell angebaute Weinsorte, bei der mehrere Rebsorten zusammen im Weingarten wachsen und gemeinsam vinifiziert werden"}, {"kategorie": "", "text": "Der [[Gemischte]] Satz gilt als Aushängeschild des Wiener Weins und ist seit 2013 mit einer geschützten Ursprungsbezeichnung versehen. Neben Weißwein wird in den Wiener Weinbergen auch Rotwein wie [[Zweigelt]] und [[Blauer]] Portugieser produziert"}, {"kategorie": "", "text": "Ein integraler Bestandteil der Wiener Weinberge ist die Heurigenkultur, die mit den traditionellen Wiener Weinschenken verbunden ist. In [[Heurigenlokalen]], die oft von Winzern betrieben werden, wird der eigene Wein ausgeschenkt, begleitet von lokalen Spezialitäten."}]'::jsonb, ''),
  ('wiina-weinbau', 'Wiina Weinbau', '', '', '', '', 'Wiener Weinbau', '[{"kategorie": "allg.", "text": "\"einzigartiger und bedeutender Bestandteil der städtischen Kultur und Wirtschaft Wiens\""}, {"kategorie": "", "text": "Die Stadt Wien gehört zu den wenigen Metropolen weltweit, in denen Weinbau innerhalb der Stadtgrenzen betrieben wird. Der Weinbau hat in Wien eine jahrhundertealte Tradition und ist tief in der Geschichte und Lebensart der Stadt verwurzelt"}, {"kategorie": "", "text": "Der Weinbau in Wien geht bis auf die Römerzeit zurück, als bereits Reben in der Region kultiviert wurden. Im Mittelalter erlebte der Wiener Weinbau eine Blütezeit, und der Weinhandel wurde zu einem wichtigen Wirtschaftszweig der Stadt. Kaiser [[Friedrich]] III. gewährte den Winzern im 15. Jahrhundert besondere Privilegien, die den Weinbau förderten"}, {"kategorie": "", "text": "Der Wiener Weinbau konzentriert sich vor allem auf den 19. Bezirk ([[Döbling]]) mit den Stadtteilen [[Grinzing]], [[Nussdorf]], [[Sievering]], [[Salmannsdorf]] und [[Neustift]] am Walde, sowie auf Gebiete im 21. Bezirk Floridsdorf ([[Stammersdorf]]), im 23. Bezirk Liesing ([[Mauer]]) und im 10. Bezirk Favoriten ([[Oberlaa]]). Insgesamt umfasst der Wiener Weinbau eine Fläche von etwa 700 Hektar"}, {"kategorie": "", "text": "Wien ist bekannt für eine große Vielfalt an weißen und roten Rebsorten. Zu den wichtigsten weißen Rebsorten gehören: [[Grüner]] Veltliner, [[Riesling]], [[Welschriesling]] und [[Weißburgunder]]. Unter den Rotweinsorten sind [[Zweigelt]] und [[Blauer]] Portugieser am weitesten verbreitet"}, {"kategorie": "", "text": "Eine besondere Spezialität des Wiener Weinbaus ist der Wiener [[Gemischte]] Satz. Bei diesem traditionellen Weintyp werden verschiedene Rebsorten auf demselben Weinberg angebaut und zusammen vinifiziert. Diese Methode führt zu einem komplexen und vielschichtigen Wein, der seit 2013 eine geschützte Ursprungsbezeichnung trägt"}, {"kategorie": "", "text": "Die Heurigen sind eine zentrale Tradition des Wiener Weinbaus. Dabei handelt es sich um typische Weinschenken, in denen die Winzer ihren eigenen Wein ausschenken. Sie sind besonders in den Weinbaugebieten Wiens zu findenund bieten neben Wein auch traditionelle Wiener Speisen an, wobei die Gästein entspannter Atmosphäre den neuesten Jahrgang des Weines probieren können."}]'::jsonb, ''),
  ('wiina-wein', 'Wiina Wein', '', '', '', '', 'Wiener Wein', '[{"kategorie": "allg.", "text": "\"einzigartiger und bedeutender Bestandteil der städtischen Kultur und Wirtschaft Wiens\""}, {"kategorie": "", "text": "Die Stadt Wien gehört zu den wenigen Metropolen weltweit, in denen Weinbau innerhalb der Stadtgrenzen betrieben wird. Der Weinbau hat in Wien eine jahrhundertealte Tradition und ist tief in der Geschichte und Lebensart der Stadt verwurzelt"}, {"kategorie": "", "text": "Der Weinbau in Wien geht bis auf die Römerzeit zurück, als bereits Reben in der Region kultiviert wurden. Im Mittelalter erlebte der Wiener Weinbau eine Blütezeit, und der Weinhandel wurde zu einem wichtigen Wirtschaftszweig der Stadt. Kaiser [[Friedrich]] III. gewährte den Winzern im 15. Jahrhundert besondere Privilegien, die den Weinbau förderten"}, {"kategorie": "", "text": "Der Wiener Weinbau konzentriert sich vor allem auf den 19. Bezirk ([[Döbling]]) mit den Stadtteilen [[Grinzing]], [[Nussdorf]], [[Sievering]], [[Salmannsdorf]] und [[Neustift]] am Walde, sowie auf Gebiete im 21. Bezirk Floridsdorf ([[Stammersdorf]]), im 23. Bezirk Liesing ([[Mauer]]) und im 10. Bezirk Favoriten ([[Oberlaa]]). Insgesamt umfasst der Wiener Weinbau eine Fläche von etwa 700 Hektar"}, {"kategorie": "", "text": "Wien ist bekannt für eine große Vielfalt an weißen und roten Rebsorten. Zu den wichtigsten weißen Rebsorten gehören: [[Grüner]] Veltliner, [[Riesling]], [[Welschriesling]] und [[Weißburgunder]]. Unter den Rotweinsorten sind [[Zweigelt]] und [[Blauer]] Portugieser am weitesten verbreitet"}, {"kategorie": "", "text": "Eine besondere Spezialität des Wiener Weinbaus ist der Wiener [[Gemischte]] Satz. Bei diesem traditionellen Weintyp werden verschiedene Rebsorten auf demselben Weinberg angebaut und zusammen vinifiziert. Diese Methode führt zu einem komplexen und vielschichtigen Wein, der seit 2013 eine geschützte Ursprungsbezeichnung trägt"}, {"kategorie": "", "text": "Die Heurigen sind eine zentrale Tradition des Wiener Weinbaus. Dabei handelt es sich um typische Weinschenken, in denen die Winzer ihren eigenen Wein ausschenken. Sie sind besonders in den Weinbaugebieten Wiens zu findenund bieten neben Wein auch traditionelle Wiener Speisen an, wobei die Gästein entspannter Atmosphäre den neuesten Jahrgang des Weines probieren können."}]'::jsonb, ''),
  ('ottakringa-friidhof', 'Ottakringa Friidhof', '', '', '', '', 'Ottakringer Friedhof', '[{"kategorie": "", "text": "Der Ottakringer Friedhof liegt an der [[Gallitzinstraße]] am Rand des [[Wienerwalds]]. Der Friedhof erstreckt sich über eine Fläche von etwa 72.000 Quadratmetern und bietet Platz für zahlreiche Gräber, darunter auch historische Grabstätten"}, {"kategorie": "", "text": "Am Ottakringer Friedhof sind einige bekannte Persönlichkeiten beigesetzt, darunter Hansl Schmid (Wienerliedsänger). Auf dem Friedhof fanden zudem auch viele Opfer der [[Februarkämpfe]] von 1934 ihre letzte Ruhestätte"}, {"kategorie": "", "text": "Der Ottakringer Friedhof dient der Bevölkerung Ottakrings als zentrale Begräbnisstätte, die seit dem 19. Jahrhundert besteht."}]'::jsonb, ''),
  ('feiahoin-simmaring', 'Feiahoin Simmaring', '', '', '', '', 'Feuerhalle Simmering', '[{"kategorie": "allg.", "text": "\"ältestes und bekanntestes Krematorium in Wien\""}, {"kategorie": "", "text": "Es befindet sich im 11. Wiener Gemeindebezirk ([[Simmering]]), wurde 1922 eröffnet und gilt als ein bedeutendes architektonisches und kulturelles Denkmal"}, {"kategorie": "", "text": "Die Feuerhalle Simmering ist in der Zentralanstalt für Bestattungswesen integriert und spielt eine zentrale Rolle in der Wiener Kremationskultur"}, {"kategorie": "", "text": "Die Feuerhalle Simmering wurde in einer Zeit errichtet, als die Feuerbestattung in Wien zunehmend an Akzeptanz gewann. Die Einführung der Kremation als Bestattungsform wurde durch die Wiener Kremationsbewegung stark vorangetrieben, die sich für eine modernere und hygienischere Form der Bestattung einsetzte. Die Anlage wurde nach den Plänen des Architekten Clemens Holzmeister erbaut und ist ein Beispiel für die damals populäre expressionistische Architektur"}, {"kategorie": "", "text": "Die Feuerhalle Simmering wurde am 17. Dezember 1922 eröffnet und war das erste Krematorium in Wien. Sie gehört heute zum [[Zentralfriedhof]] und ist auch als Urnenhain bekannt"}, {"kategorie": "", "text": "Das zentrale Gebäude wird von einem hohen Kuppelturm dominiert, der von weiten Hallen und Arkadengängen umgeben ist. Diese Gestaltung verleiht der Feuerhalle ein ehrwürdiges und monumentales Erscheinungsbild"}, {"kategorie": "", "text": "Die Anlage umfasst auch einen Urnenhain, der als Friedhof für Urnenbestattungen dient. Die parkähnliche Anlage bietet Platz für Urnengräber und ist von alten Bäumen und Gärten umgeben, die eine ruhige und friedliche Atmosphäre schaffen"}, {"kategorie": "", "text": "Die Feuerhalle Simmering ist bis heute ein wichtiger Ort für Feuerbestattungen in Wien. Viele prominente Persönlichkeiten, darunter Udo Jürgens (österreichischer Schlagersänger), wurden hier eingeäschert."}]'::jsonb, ''),
  ('hiitzinga-plotz', 'Hiitzinga Plotz', '', '', '', '', 'Hietzinger Platz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Er markiert das historische und geografische Zentrum des Bezirks, liegt an einer der wichtigsten Verkehrsknotenpunkte Hietzings und verbindet die [[Hietzinger]] Hauptstraße, die [[Maxingstraße]] und weitere wichtige Straßen des Bezirks. Der Platz ist sowohl ein Verkehrsdrehkreuz als auch ein beliebter Treffpunkt im Bezirk"}, {"kategorie": "", "text": "Der Hietzinger Platz befindet sich nahe dem Haupteingang zum Schlosspark Schönbrunn, was ihn zu einem beliebten Ausgangspunkt für Besucher des [[Schlosses]] Schönbrunn, des [[Tiergartens]] Schönbrunn und der [[Pfarrkirche]] Hietzing macht"}, {"kategorie": "", "text": "Der Hietzinger Platz ist von historisch bedeutsamen Gebäuden und Denkmälern umgeben. Darunter befinden sich mehrere Villen aus der Gründerzeit, die den Platz umrahmen und den noblen Charakter des Bezirks Hietzing unterstreichen. Auch das prächtige Gebäude der ehemaligen Kaiserlichen Wagenremise ist in unmittelbarer Nähe"}]'::jsonb, ''),
  ('noschmoakd-flohmoakd', 'Noschmoakd-Flohmoakd', '', '', '', '', 'Naschmarkt-Flohmarkt', '[{"kategorie": "allg.", "text": "\"einer der bekanntesten und größten Flohmärkte in Wien\""}, {"kategorie": "", "text": "Er findet jeden Samstag von 06:30 bis 14:00 Uhr entlang des berühmten [[Naschmarkts]] im 6. Wiener Gemeindebezirk ([[Mariahilf]]) statt"}, {"kategorie": "", "text": "Der Markt zieht sowohl Einheimische als auch Touristen an, die nach Antiquitäten, Sammlerstücken, Kleidung, Büchern, Schallplatten und vielem mehr suchen"}, {"kategorie": "", "text": "Er befindet sich entlang der [[Linken]] Wienzeile, in der Nähe der U-Bahn-Station [[Kettenbrückengasse]]"}, {"kategorie": "", "text": "Der Flohmarkt ist ein lebhafter Treffpunkt, an dem man stöbern, feilschen und Schnäppchen finden kann. Die Vielfalt der Stände und die lebendige Stimmung machen ihn zu einem einzigartigen Erlebnis, das von den Bewohnern Wiens und Touristen gleichermaßen geschätzt wird."}]'::jsonb, ''),
  ('johann-staud-schdrossn', 'Johann-Staud-Schdrossn', '', '', '', '', 'Johann-Staud-Straße', '[{"kategorie": "allg.", "text": "bedeutende Straße, die sowohl durch den 16. Bezirk ([[Ottakring]]) als auch durch den 14. Bezirk ([[Penzing]]) verläuft"}, {"kategorie": "", "text": "Sie führt die Hänge des [[Wienerwalds]] hinauf zur [[Jubiläumswarte]] im Gebiet des [[Gallitzinbergs]] (auch Wilhelminenberg genannt)  und in entgegengesetzter Richtung bis in den 14. Wiener Gemeindebezirk ([[Penzing]]), wo sie ist ein wichtiger Zugangspunkt zu den [[Steinhofgründen]] und dem [[Dehnepark]] ist"}, {"kategorie": "", "text": "Die Straße ist nach Johann Staud, einem Wiener Gemeindepolitiker und ehemaligen Bezirksvorsteher von Ottakring, benannt. Staud setzte sich für die Entwicklung und Verbesserung der Infrastruktur in Ottakring ein, und die Benennung der Straße ehrt seine Verdienste für den Bezirk."}]'::jsonb, ''),
  ('linza-schdrossn', 'Linza Schdrossn', '', '', '', '', 'Linzer Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 14. Wiener Gemeindebezirk ([[Penzing]])\""}, {"kategorie": "", "text": "Sie beginnt in der Nähe des [[Schlosses]] Schönbrunn und führt stadtauswärts in westlicher Richtung. Dabei durchquert sie über eine Länge von 6,6 km den Stadtteil [[Hütteldorf]] und endet im Bereich der Wiener Stadtgrenze in der Nähe von Purkersdorf, wo sie in die Westautobahn (A1) übergeht"}, {"kategorie": "", "text": "Die Linzer Straße gehört zu den ältesten und bedeutendsten Ausfallstraßen Wiens. Sie war Teil der Westlichen Reichsstraße, die Wien mit Städten wie St. Pölten und Linz verband. Auch heute ist die Straße eine wichtige Route für den Pendlerverkehr und verbindet zentrale Stadtteile mit den Außenbezirken"}, {"kategorie": "", "text": "In [[Hütteldorf]], nahe der Linzer Straße, liegt auch das Heimstadion des Fußballklubs [[Rapid]] Wien, das \"Allianz Stadion\"."}]'::jsonb, ''),
  ('penzinga-schdrossn', 'Penzinga Schdrossn', '', '', '', '', 'Penzinger Straße', '[{"kategorie": "allg.", "text": "zentrale Verkehrsachse im 14. Wiener Gemeindebezirk ([[Penzing]]), die sowohl verkehrstechnisch als auch historisch eine wichtige Rolle spielt"}, {"kategorie": "", "text": "Sie verläuft durch ein dicht besiedeltes Wohngebiet im westlichen Teil Wiens und verbindet den Bezirk Penzing mit den umliegenden Bezirken und zentralen Straßen der Stadt"}, {"kategorie": "", "text": "Die Penzinger Straße gehört zu den ältesten Verkehrsstraßen des Bezirks Penzing. Der Stadtteil selbst entwickelte sich im Laufe des 19. Jahrhunderts, nachdem er 1892 in die Stadt Wien eingemeindet wurde"}, {"kategorie": "", "text": "Entlang der Penzinger Straße befinden sich mehrere historische Wohngebäude und Sehenswürdigkeiten, wie das [[Palais]] Cumberland, das [[Technische]] Museum Wien oder das [[Schloss]] Schönbrunn, das nur wenige Minuten entfernt liegt."}]'::jsonb, ''),
  ('palaeae-cumberland', 'Palää Cumberland', '', '', '', '', 'Palais Cumberland', '[{"kategorie": "allg.", "text": "prächtiges historisches Gebäude an der Penzinger Straße im 14. Wiener Gemeindebezirk (Penzing)"}, {"kategorie": "", "text": "Es ist nach Ernst August von Cumberland, dem Herzog von Cumberland und König von Hannover, benannt"}, {"kategorie": "", "text": "Das Palais wurde in den späten 1860er Jahren errichtet und diente Ernst August von Cumberland, einem Nachfahren der britischen Königsfamilie, als Residenz während seines Exils in Wien. Er musste nach der Annexion Hannovers durch Preußen im Jahr 1866 nach Österreich fliehen, und das Palais wurde zu seiner neuen Heimat. Die Familie Cumberland lebte über Generationen in Wien, und das Palais blieb ein bedeutendes Bauwerk mit einer engen Verbindung zur europäischen Adelsgeschichte"}, {"kategorie": "", "text": "Das Palais ist ein klassischer Bau des [[Historismus]] mit prächtigen Fassaden und großzügigen Innenräumen, die den Glanz und Reichtum des 19. Jahrhunderts widerspiegeln"}, {"kategorie": "", "text": "Heute dient das Palais Cumberland als Sitz der tschechischen Botschaft in Wien. Das Gebäude steht unter Denkmalschutz und repräsentiert sowohl die lange Geschichte der diplomatischen Beziehungen als auch das Erbe der [[Habsburgermonarchie]] und des europäischen Hochadels."}]'::jsonb, ''),
  ('hiitzinga-kai', 'Hiitzinga Kai', '', '', '', '', 'Hietzinger Kai', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Sie verläuft vom Stadtteil [[Hacking]] entlang des [[Wienflusses]] und stellt eine zentrale Verbindung zwischen dem Westen Wiens und dem Stadtzentrum dar. Der Hietzinger Kai erstreckt sich im weiteren Verlauf von der [[Kennedybrücke]] in Hietzing bis zur Einmündung in die [[Linke]] Wienzeile im 6. Bezirk und ist Teil der wichtigen Einfallstraße aus Richtung Westen"}, {"kategorie": "", "text": "Entlang des Hietzinger Kais befinden sich mehrere bedeutende Sehenswürdigkeiten und Grünflächen, wie der [[Schlosspark]] Schönbrunn und der [[Tiergarten]] Schönbrunn, der älteste Zoo der Welt, sowie auch der Stadtteil [[Ober-Sankt-Veit]]"}, {"kategorie": "", "text": "Entlang des Hietzinger Kais gibt es mehrere U-Bahn-Stationen der Linie U4, die die Strecke von Hütteldorf bis in die Innenstadt abdeckt"}, {"kategorie": "", "text": "Die Straße ist stark befahren und eine wichtige Durchgangsstraße für den Pendelverkehr zwischen den äußeren Bezirken und dem Zentrum Wiens."}]'::jsonb, ''),
  ('kennedy-bruckn', 'Kennedy-Bruckn', '', '', '', '', 'Kennedy-Brücke', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsverbindung im 13. Wiener Gemeindebezirk ([[Hietzing]])\""}, {"kategorie": "", "text": "Sie führt über den [[Wienfluss]] und verbindet die Bezirke [[Hietzing]] und [[Penzing]]"}, {"kategorie": "", "text": "Ursprünglich als Hietzinger Brücke bekannt, wurde sie 1963 nach dem ehemaligen US-Präsidenten John F. Kennedy umbenannt, um seine Rolle in der internationalen Politik zu würdigen"}, {"kategorie": "", "text": "Die Kennedy-Brücke verbindet den [[Hietzinger]] Kai auf der einen Seite mit der [[Hadikstraße]] auf der anderen Seite und ist eine der zentralen Verbindungen für den Straßenverkehr und die öffentlichen Verkehrsmittel. Sie liegt in der Nähe des [[Hietzinger]] Platzes und der U-Bahn-Station Hietzing (U4)"}, {"kategorie": "", "text": "In unmittelbarer Nähe der Kennedy-Brücke befindet sich der Eingang zum berühmten [[Schlosspark]] Schönbrunn, einem der meistbesuchten Sehenswürdigkeiten Wiens, sowie zum [[Tiergarten]] Schönbrunn"}, {"kategorie": "", "text": "Die Brücke bietet auch Zugang zu den südwestlich gelegenen Erholungsgebieten des Wienerwalds und den grünen Vororten im Westen der Stadt."}]'::jsonb, ''),
  ('baunhof-braadnsee', 'Baunhof Braadnsee', '', '', '', '', 'Bahnhof Breitensee', '[{"kategorie": "allg.", "text": "wichtiger Knotenpunkt für den regionalen Pendlerverkehr im 14. Wiener Gemeindebezirk ([[Penzing]]), der andere stark frequentierte Bahnhöfe entlastet und den Bewohnern der westlichen Bezirke eine bequeme Möglichkeit bietet, schnell ins Stadtzentrum oder in andere Bezirke zu gelangen"}, {"kategorie": "", "text": "Er liegt an der [[Vorortelinie]] (S45), die Wien in einem Bogen von Hütteldorf bis Handelskai umrundet und damit eine wichtige Verkehrsverbindung innerhalb der Stadt darstellt"}, {"kategorie": "", "text": "Der Bahnhof dient hauptsächlich der Personenbeförderung und verbindet die westlichen Bezirke Wiens mit dem restlichen S-Bahn-Netz. Von hier aus erreichen Pendler wichtige Umsteigepunkte wie Wien [[Westbahnhof]], wo Anschluss an andere S-Bahn- und U-Bahn-Linien besteht"}, {"kategorie": "", "text": "Namensgeber ist der Wiener Vorort [[Breitensee]], allerdings liegt der Bahnhof bereits außerhalb der Katastralgrenze von Breitensee an der [[Hütteldorfer]] Straße."}]'::jsonb, ''),
  ('lugna-city', 'Lugna City', '', '', '', '', 'Lugner City', '[{"kategorie": "allg.", "text": "bekanntes Einkaufszentrum im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Die Lugner City befindet sich an der [[Gablenzgasse]], nahe dem Wiener [[Gürtel]]. Sie liegt zentral in Wien und ist gut mit den öffentlichen Verkehrsmitteln erreichbar, unter anderem durch die U-Bahn-Linie U6 (Station Burggasse-Stadthalle) sowie durch mehrere Bus- und Straßenbahnlinien"}, {"kategorie": "", "text": "Die Lugner-City wurde im Jahr 1990 von dem österreichischen Bauunternehmer und Wiener Original Richard \"Mörtel\" Lugner († 12. August 2024) eröffnet, nach dem das Einkaufszentrum auch benannt ist"}, {"kategorie": "", "text": "Die Lugner City ist sowohl ein Shoppingcenter als auch ein Kultur- und Veranstaltungsort, das über die Jahre zu einem beliebten Treffpunkt für Einheimische und Touristen geworden ist."}]'::jsonb, ''),
  ('baunhof-city-west', 'Baunhof-City-West', '', '', '', '', 'Bahnhof-City-West', '[{"kategorie": "allg.", "text": "modernes Einkaufs- und Dienstleistungszentrum im [[Westbahnhof]], einem der größten und wichtigsten Bahnhöfe Wiens"}, {"kategorie": "", "text": "Die BahnhofCity Wien West befindet sich direkt im Westbahnhof, der an der [[Mariahilfer]] Straße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Sie bietet auf mehreren Ebenen eine Mischung aus Geschäften, Gastronomiebetrieben und Dienstleistungen, die sowohl den Bedürfnissen von Pendlern als auch von Anwohnern gerecht werden"}, {"kategorie": "", "text": "Das Zentrum wurde im Rahmen der umfassenden Renovierung des Wiener Westbahnhofs im Jahr 2011 eröffnet und verbindet den Bahnhof mit einem vielfältigen Shopping- und Gastronomieangebot"}, {"kategorie": "", "text": "Es dient sowohl Reisenden als auch der lokalen Bevölkerung als Einkaufs- und Verkehrsdrehkreuz."}]'::jsonb, ''),
  ('richard-wagna-plotz', 'Richard-Wagna-Plotz', '', '', '', '', 'Richard-Wagner-Platz', '[{"kategorie": "allg.", "text": "kleiner, repräsentativer Platz im 16. Wiener Gemeindebezirk ([[Ottakring]]), der nach dem berühmten deutschen Komponisten Richard Wagner benannt ist"}, {"kategorie": "", "text": "Der Richard-Wagner-Platz liegt im westlichen Teil von Ottakring, direkt an der [[Thaliastraße]]"}, {"kategorie": "", "text": "Er befindet sich in einem typischen städtischen Gebiet und ist von Wohnhäusern und Geschäften umgeben"}, {"kategorie": "", "text": "Aufgrund seiner Größe und Lage dient der Richard-Wagner-Platz eher als eine lokale Verkehrs- und Ruhezone als ein zentraler Knotenpunkt"}, {"kategorie": "", "text": "Auf dem Richard-Wagner-Platz befindet sich der 2009 enthüllte Hiroshima-Gedenkstein, ein Mahnmal in Erinnerung an die Schrecken des Atombomben-Abwurfs über die japanische Stadt Hiroshima 1945. Zugleich erinnert das Denkmal an den 1982 in seinem Heimatbezirk verstorbenen Jugendschriftsteller Karl Bruckner. Bruckner veröffentlichte 1961 das Buch \"Sadako will leben\", in dem er den Leidensweg einer Strahlenvergiftung beschreibt."}]'::jsonb, ''),
  ('pfoakiachn-braadnsee', 'Pfoakiachn Braadnsee', '', '', '', '', 'Pfarrkirche Breitensee', '[{"kategorie": "allg.", "text": "römisch-katholische Pfarrkirche im 14. Wiener Gemeindebezirk ([[Penzing]]), konkret im Stadtteil [[Breitensee]]"}, {"kategorie": "", "text": "Die Pfarrkirche Breitensee, auch als Pfarrkirche Mariä Geburt bekannt, wurde im späten 19. Jahrhundert erbaut und am 7. Oktober 1899 geweiht. Sie wurde vom Architekten Richard Jordan entworfen und stellt ein klassisches Beispiel für den neugotischen Baustil in Wien dar"}, {"kategorie": "", "text": "Die Kirche beeindruckt durch ihre hohen Türme, spitzbogigen Fenster und die kunstvollen Verzierungen, die für diese architektonische Epoche typisch sind"}, {"kategorie": "", "text": "Der Innenraum der Kirche ist mit Glasfenstern und kunstvollen Altären ausgestattet, die dem Bauwerk eine beeindruckende und feierliche Atmosphäre verleihen."}]'::jsonb, ''),
  ('pfoakiachn-nei-ottakring', 'Pfoakiachn Nei-Ottakring', '', '', '', '', 'Pfarrkirche Neu-Ottakring', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 16. Wiener Gemeindebezirk ([[Ottakring]]), auch bekannt als \"Pfarrkirche zur Heiligen Familie\""}, {"kategorie": "", "text": "Sie ist eines der wichtigsten religiösen Gebäude des Stadtteils Neu-Ottakring und wurde wurde zwischen 1894 und 1898 nach Plänen des Architekten Franz von Neumann errichtet und im Jahr 1898 geweiht"}, {"kategorie": "", "text": "Sie ist im historistischen Stil erbaut, wobei insbesondere [[neogotische]] Elemente das Gebäude prägen. Der Bau wurde notwendig, da Ottakring sich durch die Industrialisierung zu einem dicht besiedelten Arbeiterbezirk entwickelte"}, {"kategorie": "", "text": "Die Kirche ist eine imposante dreischiffige Basilika mit zwei prächtigen Türmen, die weit über die umliegenden Gebäude hinausragen. Die hohen, spitzbogigen Fenster, Strebepfeiler und das große [[Rosettenfenster]] an der Fassade sind charakteristische Elemente des neugotischen Stils"}, {"kategorie": "", "text": "Die Kirche zur Heiligen Familie zeichnet sich durch ihre beeindruckende Architektur und ihre Rolle als Wahrzeichen des Bezirks Ottakring aus. Ihre imposante Größe und kunstvolle Gestaltung machen sie zu einem der bedeutendsten Sakralbauten im Westen Wiens."}]'::jsonb, ''),
  ('ottakringa-woid', 'Ottakringa Woid', '', '', '', '', 'Ottakringer Wald', '[{"kategorie": "allg.", "text": "\"großes Naherholungsgebiet im westlichen Teil von Wien, das sich im 16. Wiener Gemeindebezirk ([[Ottakring]]) befindet\""}, {"kategorie": "", "text": "Er liegt am Rand des [[Wienerwaldes]] und erstreckt sich vom Südhang des Rosentals an der Grenze zum 14. Bezirk ([[Penzing]]) über den [[Gallitzinberg]], nach Norden über die [[Jubiläumswarte]] und die Kreuzeiche bis zum Moosgraben an der Grenze zum 17. Bezirk (Hernals)"}, {"kategorie": "", "text": "Der Ottakringer Wald umfasst eine Fläche von 192 Hektar - das sind 2,5 Prozent des gesamten Waldes in Wien"}, {"kategorie": "", "text": "Der Ottakringer Wald dient als beliebtes Ziel für Wanderungen, Spaziergänge und Naturerholung, da er eine ruhige Umgebung in unmittelbarer Stadtnähe bietet."}]'::jsonb, ''),
  ('oide-pfoakiachn-poetzleinsduaf', 'Oide Pfoakiachn Pötzleinsduaf', '', '', '', '', 'Alte Pfarrkirche Pötzleinsdorf', '[{"kategorie": "allg.", "text": "\"historische römisch-katholische Kirche im 18. Wiener Gemeindebezirk ([[Währing]]), auch \"Ägidiuskirche\" genannt"}, {"kategorie": "", "text": "Sie ist dem heiligen Ägidius geweiht und eines der ältesten sakralen Gebäude in diesem Bezirk"}, {"kategorie": "", "text": "Die Kirche befindet sich im Stadtteil [[Pötzleinsdorf]], einem der gehobenen und grüneren Wohngebiete am Rande des [[Wienerwaldes]]"}, {"kategorie": "", "text": "Die Ägydiuskirche ist eine spätbarocke, einschiffige Kirche, die aus einem rechteckigen Raum mit abgerundeten Ecken besteht. Auffällig ist der quadratische, in die Fassade einbezogene Turm. Die ursprünglichen Glocken wurden in den beiden Weltkriegen für Rüstungszwecke abtransportiert, heute verfügt der Turm über vier Glocken. Vor der Kirche befinden sich an der nordseitigen Mauer zwei barocke Grabsteine. Aus einem Maskaron in einer Wandnische fließt das Wasser der Pötzleinsdorfer Quelle, der einst heilkräftige Wirkung nachgesagt wurde"}, {"kategorie": "", "text": "Zentrales Element des Innenraums ist der Hauptaltar mit der Darstellung der Kreuzigung Christi von Johann Nepomuk Steiner. Weiters befindet sich im Vorderteil der Kirche ein großer Tabernakel mit anbetenden Engeln und darüber ein ikonenartiges Marienbild aus dem 17. Jahrhundert. Neben dem Hauptaltar verfügt die Ägydiuskirche auch über zwei Seitenaltäre, von denen einer den Kirchenpatron zeigt (Darstellung von Johann Nepomuk Steiner), ein zweiter den heiligen Antonius von Padua"}, {"kategorie": "", "text": "Trotz ihrer schlichten Architektur ist die Kirche ein bedeutendes historisches und kulturelles Denkmal in Wien."}]'::jsonb, ''),
  ('augustina-bastei', 'Augustina Bastei', '', '', '', '', 'Augustiner Bastei', '[{"kategorie": "allg.", "text": "historisch bedeutender Teil der ehemaligen Wiener Stadtbefestigung, die im Bereich des 1. Wiener Gemeindebezirks ([[Innere]] Stadt) liegt"}, {"kategorie": "", "text": "Sie ist eine von ehemals zehn Bastionen (in Wien: Basteien), die ihren Namen von der nahegelegenen [[Augustinerkirche]] erhalten hat\". 1549 wurde sie „Bastei hinter den Augustinern“ genannt, 1550 „Bastei bei den Augustinern“, 1770 „Kärntner Bastei“ (hier befand sich auch das [[Kärntner]] Tor), ab 1783 taucht erstmals der Name „Augustinerbastei“ auf"}, {"kategorie": "", "text": "Wie viele Teile der [[Wiener]] Stadtmauer wurde die Augustinerbastei im Zuge der städtischen Modernisierung und des Wiener Städtewachstums im 19. Jahrhundert abgetragen. Ein großer Teil der Bastei blieb jedoch erhalten und bildet heute das Fundament für das [[Albertina-Museum]]"}]'::jsonb, ''),
  ('wiina-schdodtmaua', 'Wiina Schdodtmaua', '', '', '', '', 'Wiener Stadtmauer', '[{"kategorie": "wörtlich", "text": "\"Bestigungsanlage, welche die Stadt Wien bis ins 19. Jahrhundert umschloss\""}, {"kategorie": "hist.", "text": "Sie diente dem Schutz der Stadt vor Angriffen und wurde im Laufe der Jahrhunderte mehrmals erweitert und verstärkt"}, {"kategorie": "", "text": "Die ersten Befestigungen wurden bereits im 12. Jahrhundert errichtet, aber die Wiener Stadtmauer wurde im Laufe der folgenden Jahrhunderte immer weiter ausgebaut, insbesondere im 16. und 17. Jahrhundert, um die Stadt gegen die Bedrohungen durch das Osmanische Reich zu schützen. Ein besonders bedeutender Ausbau erfolgte nach der ersten Türkenbelagerung im Jahr 1529"}, {"kategorie": "", "text": "Die Stadtmauer bestand aus mehreren Verteidigungselementen, darunter: Hauptmauer (massive Steinmauer, die die Stadt umgab), Basteien (Ausbuchtungen, die zur Aufstellung von Kanonen dienten und einen besseren Verteidigungswinkel ermöglichten"}, {"kategorie": "", "text": "Zwischen 1857 und 1864 ordnete Kaiser Franz Joseph den Abriss der Mauer an, um Platz für den Wiener Ring, eine Prachtstraße, zu schaffen. Die Ringstraße, die das Stadtzentrum umschließt, verläuft heute entlang der ehemaligen Stadtmauer."}]'::jsonb, ''),
  ('hintare-zollaumtsschdrossn', 'Hintare Zollaumtsschdrossn', '', '', '', '', 'Hintere Zollamtsstraße', '[{"kategorie": "allg.", "text": "\"belebte Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie verläuft vom [[Donaukanal]] bis zum Bereich um den [[Wiener]] Stadtpark und ist verkehrstechnisch eine wichtige Verbindung in diesem Teil Wiens"}, {"kategorie": "", "text": "Die Hintere Zollamtsstraße ist nach dem 1840-1844 von Paul Sprenger errichteten Zolloberamtsgebäude (Hauptzollamt, Nummer 4) benannt, das im Zweiten Weltkrieg völlig zerstört wurde"}, {"kategorie": "", "text": "Die Hintere Zollamtsstraße war im Zusammenhang mit dem Warenverkehr und den Zollabfertigungen von Bedeutung, da der Donaukanal eine zentrale Rolle für den Transport von Gütern spielte. Die Straße erhielt ihren Namen, da sie sich hinter dem ehemaligen Wiener Hauptzollamt befand"}, {"kategorie": "", "text": "Heute dient die Straße vor allem dem Verkehr und ist weniger eine Wohngegend als vielmehr ein funktionaler Teil der städtischen Infrastruktur in Wien."}]'::jsonb, ''),
  ('vuadare-zollaumtsschdrossn', 'Vuadare Zollaumtsschdrossn', '', '', '', '', 'Vordere Zollamtsstraße', '[{"kategorie": "allg.", "text": "\"1. (allg.) \"belebte Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie verläuft vom [[Donaukanal]] bis zum Bereich um den [[Wiener]] Stadtpark und ist verkehrstechnisch eine wichtige Verbindung in diesem Teil Wiens"}, {"kategorie": "", "text": "Die Vordere Zollamtsstraße ist nach dem 1840-1844 von Paul Sprenger errichteten Zolloberamtsgebäude (Hauptzollamt, Nummer 4) benannt, das im Zweiten Weltkrieg völlig zerstört wurde"}, {"kategorie": "", "text": "Die Vordere Zollamtsstraße war im Zusammenhang mit dem Warenverkehr und den Zollabfertigungen von Bedeutung, da der Donaukanal eine zentrale Rolle für den Transport von Gütern spielte. Die Straße erhielt ihren Namen, da sie sich vor dem ehemaligen Wiener Hauptzollamt befand"}, {"kategorie": "", "text": "Heute dient die Straße vor allem dem Verkehr und ist weniger eine Wohngegend als vielmehr ein funktionaler Teil der städtischen Infrastruktur in Wien."}]'::jsonb, ''),
  ('obare-viaduktgossn', 'Obare Viaduktgossn', '', '', '', '', 'Obere Viaduktgasse', '[{"kategorie": "allg.", "text": "\"schmale Straße im [[Weißgerberviertel]] im 3. Wiener Gemeindebezirk ([[Landstraße]]), die sich zwischen dem [[Donaukanal]] und dem [[Radetzkyplatz]] erstreckt\""}, {"kategorie": "", "text": "Sie liegt in einem urbanen Gebiet und verläuft parallel zur [[Unteren]] Viaduktgasse \"jenseits des Viadukts\""}, {"kategorie": "", "text": "Die Straße ist nach ihrer Lage an den Viadukten der (1857 erbauten) Verbindungsbahn zwischen [[Südbahnhof]] (heute [[Hauptbahnhof]]) und [[Nordbahnhof]] benannt, an der die schmale Gasse entlangführt"}, {"kategorie": "", "text": "Ein Viadukt ist eine Brückenstruktur, die Straßen, Flüsse oder Täler überquert. In diesem Fall bezieht sich der Name auf die Bahnviadukte, die über die Gasse und den umliegenden Bereich führen"}, {"kategorie": "", "text": "Die Obere Viaduktgasse ist heute eine ruhige Wohnstraße mit einigen Geschäften und Gewerbebetrieben. In der Umgebung befinden sich zudem Bürogebäude, Restaurants und soziale Einrichtungen."}]'::jsonb, ''),
  ('untare-viaduktgossn', 'Untare Viaduktgossn', '', '', '', '', 'Untere Viaduktgasse', '[{"kategorie": "allg.", "text": "\"schmale Straße im [[Weißgerberviertel]] im 3. Wiener Gemeindebezirk ([[Landstraße]]), die sich zwischen dem [[Donaukanal]] und dem [[Radetzkyplatz]] erstreckt\""}, {"kategorie": "", "text": "Sie liegt in einem urbanen Gebiet und verläuft parallel zur [[Oberen]] Viaduktgasse \"diesseits des Viadukts\""}, {"kategorie": "", "text": "Die Straße ist nach ihrer Lage an den Viadukten der (1857 erbauten) Verbindungsbahn zwischen [[Südbahnhof]] (heute [[Hauptbahnhof]]) und [[Nordbahnhof]] benannt, an der die schmale Gasse entlangführt"}, {"kategorie": "", "text": "Ein Viadukt ist eine Brückenstruktur, die Straßen, Flüsse oder Täler überquert. In diesem Fall bezieht sich der Name auf die Bahnviadukte, die über die Gasse und den umliegenden Bereich führen"}, {"kategorie": "", "text": "Die Untere Viaduktgasse ist heute eine ruhige Wohnstraße mit einigen Geschäften und Gewerbebetrieben. In der Umgebung befinden sich zudem Bürogebäude, Restaurants und soziale Einrichtungen."}]'::jsonb, ''),
  ('aua-woesboch-park', 'Aua-Wösboch-Park', '', '', '', '', 'Auer-Welsbach-Park', '[{"kategorie": "allg.", "text": "\"Grünanlage im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]) sowie im 14. Bezirk ([[Penzing]])\";  2.Der Park befindet sich in unmittelbarer Nähe zum [[Schloss]] Schönbrunn und ist nach dem österreichischen Chemiker und Erfinder Carl Auer von Welsbach (1858–1929) benannt, der für seine Entdeckungen im Bereich der Beleuchtung und Metalle bekannt ist"}, {"kategorie": "", "text": "Auf dem Parkareal befand sich bis ins 19. Jahrhundert der Penzinger Ziegelofen. 1890 wurde der Schönbrunner Vorpark angelegt, der mit seiner englischen Gartengestaltung einen bewussten Gegensatz zur französischen Gartenanlage des Schlosses bildet"}, {"kategorie": "", "text": "1992 wurde das Parkareal, bis dahin im 14. Bezirk, in den östlich jenseits der [[Winckelmannstraße]] anschließenden 15. Bezirk umgegliedert, um in diesem den Grünflächenanteil zu erhöhen"}, {"kategorie": "", "text": "Heute ist der Park eine grüne Oase inmitten der Stadt und verbindet historische Bedeutung mit modernen Freizeitmöglichkeiten. Er dient als Rückzugsort für Familien, Sportbegeisterte und Touristen gleichermaßen und erinnert mit seinem Namen an den berühmten Erfinder Carl Auer von Welsbach, der maßgeblich zur technologischen Entwicklung des späten 19. und frühen 20. Jahrhunderts beigetragen hat."}]'::jsonb, ''),
  ('palaeae-lobkowitz', 'Palää Lobkowitz', '', '', '', '', 'Palais Lobkowitz', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten Barockpalais in Wien\""}, {"kategorie": "", "text": "Es befindet sich am [[Lobkowitzplatz]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es wurde im späten 17. Jahrhundert erbaut und ist eng mit der Adelsfamilie Lobkowitz verbunden, die zu den einflussreichsten Familien des [[Habsburgerreichs]] zählte. Heute beherbergt das Palais das [[Theatermuseum]], eine bedeutende kulturelle Institution Wiens"}, {"kategorie": "", "text": "Das Palais wurde zwischen 1685 und 1687 im Auftrag von Graf Philipp Sigmund von Dietrichstein erbaut, ging jedoch bald in den Besitz der Familie Lobkowitz über. Fürst Ferdinand von Lobkowitz (1655–1715) ließ es ausbauen und prägte den repräsentativen Charakter des Gebäudes. Die Lobkowitz-Familie nutzte das Palais als ihre Wiener Residenz und war für ihre enge Verbindung zur Kunst- und Musikszene bekannt"}, {"kategorie": "", "text": "Besonders Fürst Franz Joseph Maximilian von Lobkowitz (1772–1816) spielte eine herausragende Rolle als Mäzen und Förderer der Künste. Er war ein enger Freund von Ludwig van Beethoven und unterstützte den Komponisten großzügig. Beethoven widmete ihm mehrere Werke, darunter seine berühmte 3. Sinfonie (\"Eroica\"), die ursprünglich zu Ehren Napoleons geschrieben war, später aber dem Fürsten Lobkowitz gewidmet wurde, nachdem Beethoven seine Meinung über Napoleon änderte"}, {"kategorie": "", "text": "Das Palais ist ein beeindruckendes Beispiel barocker Architektur. Es verfügt über eine prunkvolle Fassade und ist im Inneren reich mit kunstvollen Fresken und Dekorationen ausgestattet. Die repräsentativen Räume, darunter der prunkvolle Festsaal, wurden für gesellschaftliche und kulturelle Anlässe genutzt. Der Baustil spiegelt den barocken Hang zur Pracht und Repräsentation wider, der für Adelspaläste dieser Zeit typisch war"}, {"kategorie": "", "text": "Heute beherbergt das Palais Lobkowitz das [[Theatermuseum]], das eine der größten Sammlungen zur Geschichte des Theaters in Österreich und Europa zeigt. Das Museum umfasst eine beeindruckende Sammlung von Theaterrequisiten, Kostümen, Bühnenbildern und Dokumenten aus verschiedenen Epochen. Neben der Dauerausstellung finden regelmäßig Sonderausstellungen, Vorträge und kulturelle Veranstaltungen statt."}]'::jsonb, ''),
  ('haundlskej-baunhof', 'Haundlskej-Baunhof', '', '', '', '', 'Handelskai-Bahnhof', '[{"kategorie": "allg.", "text": "\"wichtiger Verkehrsknotenpunkt im 20. Wiener Gemeindebezirk ([[Brigittenau]]), der sowohl für den öffentlichen Nahverkehr als auch für den Regional- und Fernverkehr eine zentrale Rolle spielt\""}, {"kategorie": "", "text": "Der Bahnhof befindet sich entlang des [[Handelskai]], einer Hauptverkehrsstraße, die parallel zur [[Donau]] verläuft, und verbindet mehrere Verkehrsmittel wie [[U-Bahn]], [[S-Bahn]], [[Straßenbahn]] und Buslinien miteinander"}, {"kategorie": "", "text": "Die Nähe zu bedeutenden Einrichtungen wie dem [[Millennium]] Tower und dem [[Millennium]] City-Einkaufszentrum macht den Handelskai-Bahnhof auch für Besucher und Touristen attraktiv, die die Gegend um den Donaukanal erkunden oder das Freizeitangebot in der Umgebung nutzen möchten."}]'::jsonb, ''),
  ('millenium-taua', 'Millenium Taua', '', '', '', '', 'Millenium Tower', '[{"kategorie": "allg.", "text": "\"eines der höchsten Gebäude Österreichs, welches sich im 20. Wiener Gemeindebezirk ([[Brigittenau]]), direkt an der Donau\""}, {"kategorie": "", "text": "Mit einer Höhe von 202 Metern (mit Antenne) und 50 Stockwerken wurde der Millennium Tower zu einem markanten Wahrzeichen im Norden Wiens und prägt die Skyline der Stadt"}, {"kategorie": "", "text": "Der Millennium Tower wurde zwischen 1997 und 1999 erbaut und zur Jahrtausendwende im Jahr 1999 fertiggestellt, wovon auch sein Name abgeleitet ist. Das Gebäude wurde von den Architekten Gustav Peichl, Boris Podrecca und Rudolf Weber entworfen und ist Teil des größeren [[Millennium]] City-Komplexes, der sowohl Büros als auch Freizeit- und Einkaufsflächen umfasst"}, {"kategorie": "", "text": "Das Bauwerk repräsentiert moderne Architektur mit einem Fokus auf Funktionalität und Nachhaltigkeit. Es besteht größtenteils aus Glas und Stahl, was ihm eine futuristische und gleichzeitig elegante Erscheinung verleiht."}]'::jsonb, ''),
  ('millenium-city', 'Millenium City', '', '', '', '', 'Millenium City', '[{"kategorie": "allg.", "text": "\"multifunktionaler Gebäudekomplex im 20. Wiener Gemeindebezirk ([[Brigittenau]]), der als modernes Einkaufs-, Büro- und Freizeitzentrum dient\""}, {"kategorie": "", "text": "Sie befindet sich direkt am [[Handelskai]], einem wichtigen Verkehrsknotenpunkt im Norden Wiens, und ist Teil des Areals, das auch den markanten [[Millennium Tower]] umfasst, eines der höchsten Gebäude Österreichs"}, {"kategorie": "", "text": "Die Millennium City wurde Ende der 1990er Jahre errichtet und im Jahr 1999 eröffnet, passend zur Jahrtausendwende, was der Anlage ihren Namen gibt. Der Bau wurde von den Architekten Gustav Peichl, Boris Podrecca und Rudolf Weber gestaltet und spiegelt den architektonischen Trend der Zeit wider, multifunktionale Gebäude zu errichten, die Arbeit, Einkauf und Freizeitaktivitäten an einem Ort bündeln"}, {"kategorie": "", "text": "Die Architektur der Millennium City ist modern und funktional, mit einer Glas- und Stahlfassade, die den Komplex elegant und futuristisch wirken lässt. Der [[Millennium]] Tower, der das Herzstück der Anlage bildet, ragt mit seinen 202 Metern deutlich über die umgebenden Gebäude hinaus und ist ein markantes Wahrzeichen Wiens."}]'::jsonb, ''),
  ('van-da-nuell-gossn', 'Van-da-Nüll-Gossn', '', '', '', '', 'Van-der-Nüll-Gasse', '[{"kategorie": "allg.", "text": "\"Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die nach dem berühmten österreichischen Architekten Eduard van der Nüll (1812–1868) benannt ist\""}, {"kategorie": "", "text": "Van der Nüll war einer der bedeutendsten Architekten des 19. Jahrhunderts in Wien und Mitbegründer des sogenannten Wiener [[Historismus]]. Zu seinen bekanntesten Werken gehört die [[Wiener]] Staatsoper, die er zusammen mit seinem Kollegen August Sicard von Sicardsburg entwarf"}, {"kategorie": "", "text": "Van der Nüll prägte das architektonische Erscheinungsbild der Stadt maßgeblich und war Teil des Teams, das für den Bau der Wiener Ringstraßenbauten verantwortlich war. Leider verstarb Van der Nüll kurz vor der Eröffnung der Wiener Staatsoper, sodass er die Fertigstellung seines berühmtesten Werks nicht mehr miterlebte"}, {"kategorie": "", "text": "Die Straße ist überwiegend von Wohnhäusern geprägt, wobei sich auch einige Schulen und kleinere Geschäfte in der Umgebung befinden. Der Bezirk [[Favoriten]] hat in den letzten Jahren eine starke urbane Entwicklung erfahren und ist bekannt für seine Multikulturalität und seine Nähe zu großen Infrastrukturprojekten wie dem [[Hauptbahnhof]] Wien."}]'::jsonb, ''),
  ('inzasduafa-schdrossn', 'Inzasduafa Schdrossn', '', '', '', '', 'Inzersdorfer Straße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die durch das dicht besiedelte Gebiet des Bezirks führt\""}, {"kategorie": "", "text": "Der Name der Straße leitet sich vom früher eigenständigen Ort Inzersdorf ab, der heute ein Teil des 23. Wiener Gemeindebezirks ([[Liesing]]) ist"}, {"kategorie": "", "text": "Die Inzersdorfer Straße verbindet Wohngebiete mit Gewerbegebieten und wichtigen Infrastrukturknotenpunkten"}, {"kategorie": "", "text": "Ihre zentrale Lage und die gute Anbindung an das öffentliche Verkehrsnetz machen sie zu einer wichtigen Verbindungsachse innerhalb des 10. Bezirks."}]'::jsonb, ''),
  ('doanbocha-schdrossn', 'Doanbocha Schdrossn', '', '', '', '', 'Dornbacher Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 17. Wiener Gemeindebezirk ([[Hernals]]), die den historischen Teil von [[Dornbach]] durchquert und eine zentrale Verbindung in diesem Stadtteil darstellt"}, {"kategorie": "", "text": "Die Straße verbindet den inneren Teil des Bezirks mit den höher gelegenen Gebieten am Rande des [[Wienerwalds]]"}, {"kategorie": "", "text": "Die Dornbacher Straße wurde nach dem ehemaligen Dorf [[Dornbach]] benannt, das heute ein Teil des 17. Bezirks ist. Dornbach wurde 1892 gemeinsam mit [[Neuwaldegg]] in die Stadt Wien eingemeindet"}, {"kategorie": "", "text": "Der Name \"Dornbach\" leitet sich von dem gleichnamigen Bach ab, der durch die Region fließt. Dornbach hat seinen ländlichen Charakter über die Jahrhunderte weitgehend bewahrt und ist heute ein gehobenes Wohngebiet in Wien"}, {"kategorie": "", "text": "Mit ihrer guten Verkehrsanbindung, ihrer Nähe zu Erholungsgebieten und ihrem charmanten, historischen Umfeld ist die Dornbacher Straße ein begehrter Wohnort in Wien."}]'::jsonb, ''),
  ('neiwoidegga-schdrossn', 'Neiwoidegga Schdrossn', '', '', '', '', 'Neuwaldegger Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 17. Wiener Gemeindebezirk ([[Hernals]]), die den Stadtteil [[Neuwaldegg]] mit anderen Teilen Wiens verbindet\""}, {"kategorie": "", "text": "Sie verläuft durch eine landschaftlich reizvolle Gegend und führt bis an den Rand des [[Wienerwalds]], einem großen Naherholungsgebiet im Westen Wiens"}, {"kategorie": "", "text": "Die Neuwaldegger Straße ist nach dem Stadtteil Neuwaldegg benannt, der früher ein eigenständiges Dorf war und 1892 nach Wien eingemeindet wurde. Neuwaldegg ist bekannt für seinen ländlichen Charakter, seine Villengebiete und seine Nähe zum Wienerwald. Der Stadtteil ist historisch vor allem durch das [[Schloss]] Neuwaldegg und den dazugehörigen Schlosspark geprägt"}, {"kategorie": "", "text": "Die Neuwaldegger Straße beginnt im zentralen Teil des 17. Bezirks (Hernals), und führt in nordwestlicher Richtung durch den Stadtteil [[Dornbach]] bis nach Neuwaldegg."}]'::jsonb, ''),
  ('mariabrunna-friidhof', 'Mariabrunna Friidhof', '', '', '', '', 'Mariabrunner Friedhof', '[{"kategorie": "", "text": "Der Friedhof liegt am Rand des [[Wienerwalds]] im Stadtteil [[Hadersdorf-Weidlingau]] und gehört zu den kleineren Friedhöfen Wiens, hat jedoch eine lange Geschichte, die eng mit der Entwicklung des Wallfahrtsorts Mariabrunn verbunden ist"}, {"kategorie": "", "text": "Der Friedhof befand sich südöstlich des Barfüßerklosters in Mariabrunn (\"Kloster der unbeschuhten Augustiner - ein Orden, der sich 1601 durch Abtrennung vom älteren Zweig der Augustiner-Eremiten (\"Beschuhte Augustiner\") gebildet hatte"}, {"kategorie": "", "text": "Der Waldmeister in [[Auhof]], Johann von Gruber, hatte für die Anfertigung des Kreuzes und für die Torpfosten Eichenbäume bereitgestellt sowie den Gottesacker umzäunt. Die Weihe erfolgte am 24. März 1784. Erasmus von Gretzmüller erbaute 1793 auf eigene Kosten eine Totenkammer sowie eine Gruft"}, {"kategorie": "", "text": "Der Friedhof ist durch seine bescheidene Größe und seine ländliche Lage gekennzeichnet. Er liegt in unmittelbarer Nähe zur Kirche und strahlt eine ruhige und beschauliche Atmosphäre aus, die ihn zu einem besonderen Ort der Erinnerung und Besinnung macht"}, {"kategorie": "", "text": "Am Mariabrunner Friedhof begraben ist auch Ignaz Raffalt, ein bekannter Landschafts- und Genremaler, der in Wien lebte (1800-1857)."}]'::jsonb, ''),
  ('mariabrunna-kiachn', 'Mariabrunna Kiachn', '', '', '', '', 'Mariabrunner Kirche', '[{"kategorie": "allg.", "text": "\"historische barocke Kirche im 14. Wiener Gemeindebezirk ([[Penzing]]), im Stadtteil [[Hadersdorf-Weidlingau]] am Rande des [[Wienerwalds]], auch bekannt als \"Wallfahrtskirche Mariabrunn\" bzw. \"Wallfahrtskirche Maria Heimsuchung in Mariabrunn\""}, {"kategorie": "", "text": "Sie ist das Zentrum des ehemaligen Wallfahrtsortes [[Mariabrunn]], der durch eine Quelle bekannt wurde, der heilende Kräfte zugeschrieben werden"}, {"kategorie": "", "text": "Namengebend ist eine Quelle, in der der Legende nach die heilige Gisela († 1033), Schwester Kaiser Heinrichs II. des Heiligen († 1024) und Gattin des ungarischen Königs Stephan des Heiligen († 1038), eine Marienstatue fand und durch Trinken des Wassers genas"}, {"kategorie": "", "text": "Die Mariabrunner Kirche ist ein barockes Bauwerk, das gegen Ende des 17. Jahrhunderts errichtet wurde. Sie besticht durch ihre schlichte, aber eindrucksvolle Architektur, die typisch für die sakralen Bauten der Barockzeit in Wien ist. Der Innenraum ist mit kunstvollen Altären und Skulpturen geschmückt, darunter eine Statue der Jungfrau Maria, die als Schutzpatronin der Kirche und des Ortes verehrt wird"}, {"kategorie": "", "text": "Die heilende Quelle, die unterhalb der Kirche entspringt, steht im Zentrum der Wallfahrtsgeschichte von Mariabrunn. Ihr wurde nachgesagt, dass sie körperliche und seelische Leiden heilen könne, und sie machte den Ort über die Grenzen Wiens hinaus bekannt. Die Quelle ist bis heute erhalten und wird von Pilgern und Besuchern weiterhin aufgesucht"}, {"kategorie": "", "text": "In der Nähe der Kirche befand sich einst ein Kloster, das im Laufe der Jahrhunderte mehreren Orden diente, darunter den Kapuzinern und den Augustinern. Heute ist die Umgebung von Mariabrunn ein beliebtes Ausflugsziel, das sowohl wegen seiner religiösen Bedeutung als auch wegen seiner natürlichen Schönheit geschätzt wird."}]'::jsonb, ''),
  ('camillo-sitte-gossn', 'Camillo-Sitte-Gossn', '', '', '', '', 'Camillo-Sitte-Gasse', '[{"kategorie": "allg.", "text": "\"Wohnstraße im 15. Wiener Bezirk ([[Rudolfsheim-Fünfhaus]]), die durch ein urbanes, multikulturelles Viertel verläuft\""}, {"kategorie": "", "text": "Sie befindet sich im westlichen Teil von Rudolfsheim-Fünfhaus, einem Bezirk, der durch eine Mischung aus Altbauten, Wohnhäusern und Gewerbeflächen geprägt ist"}, {"kategorie": "", "text": "Die Camillo-Sitte-Gasse wurde nach Camillo Sitte, einem Pionier des modernen Städtebaus, benannt. Sitte setzte sich für eine ästhetische und organische Gestaltung von Städten ein, im Gegensatz zur reinen Zweckmäßigkeit und Geometrie der industriellen Stadtplanung des 19. Jahrhunderts"}, {"kategorie": "", "text": "Das Viertel rund um die Camillo-Sitte-Gasse ist lebendig und multikulturell; die Nähe zur [[Schmelz]], einem großen Erholungs- und Freizeitgelände, bietet den Anwohnern auch eine Reihe von Freizeitmöglichkeiten."}]'::jsonb, ''),
  ('baumgoatna-friidhof', 'Baumgoatna Friidhof', '', '', '', '', 'Baumgartner Friedhof', '[{"kategorie": "", "text": "Er ist eine wichtige Begräbnisstätte der Stadt und dient vor allem den Bewohnern der umliegenden Bezirke als Ruhestätte. Der Friedhof ist nach dem ehemaligen Dorf [[Baumgarten]] benannt, das heute ein Stadtteil des 14. Bezirks ist"}, {"kategorie": "", "text": "Mit einer Fläche von 237.594 Quadratmetern und rund 33.200 Grabstellen ist er der fünftgrößte Friedhof Wiens"}, {"kategorie": "", "text": "Eine Besonderheit ist die Christusstatue aus dem Jahr 1903, die vom Stadtbaumeister Josef Münster gespendet wurde"}, {"kategorie": "", "text": "Die Christusstatue des Bildhauers Andreas Halbig war ursprünglich für den Dom in Gran (Ungarn) bestimmt. Nach dem Tod Halbigs ließ dessen Witwe die Apostelstatuen, für die keine Verwendung bestand, zerschlagen, der Christus fand in einem Gastgarten (14., Hadikgasse 20) Aufstellung. 1903 erwarb sie Stadtbaumeister Josef Münster und spendete sie schließlich für den Baumgartner Friedhof. 1998 wurde sie renoviert"}, {"kategorie": "", "text": "Seit 1976 besitzt der Baumgartner Friedhof über Initiative des Bezirksmuseums Penzing einen Grabsteinhain (Gruppe N), in dem kulturhistorisch wertvolle beziehungsweise anderweitig interessante Grabsteine nach Auflassung der betreffenden Grabstätten aufgestellt sind"}, {"kategorie": "", "text": "Götz Kaufmann (Schauspieler) und Ernst Klimt (Maler und Bruder von Gustav Klimt) sind am Baumgartner Friedhof begraben."}]'::jsonb, ''),
  ('pfoakiachn-grinzing', 'Pfoakiachn Grinzing', '', '', '', '', 'Pfarrkirche Grinzing', '[{"kategorie": "allg.", "text": "\"römisch-katholische Pfarrkirche an der Himmelstraße 25 im Bezirksteil [[Grinzing]] im 19. Wiener Gemeindebezirk ([[Döbling]]) in Wien, auch \"Heilig-Kreuz-Kirche\" bzw. \"Grinzinger Pfarrkriche\" genannt. Sie ist dem Heiligen Kreuz geweiht und steht unter Denkmalschutz"}, {"kategorie": "", "text": "Die Grinzinger Pfarrkirche wurde in den Jahren 1417 bis 1426 von zwölf Familien, wahrscheinlich Weinbauern, finanziert und errichtet. Damit ersparten sich die Grinzinger während der Woche den Marsch in die Heiligenstädter Pfarrkirche, die nun nur noch sonntags besucht wurde"}, {"kategorie": "", "text": "Zweimal wurde die Kirche jedoch ein Raub der Flammen. Die Kirche wurde bei den Türkenbelagerungen 1529 und 1683 zerstört und mit Hilfe des Stifts Klosterneuburg wieder aufgebaut"}, {"kategorie": "", "text": "Die Pfarrkirche Grinzing weist eine Mischung aus gotischen und barocken Stilelementen auf. Das ursprüngliche Langhaus und der Chor stammen aus der Gotik, während der Turm und einige Innendetails im Barockstil gehalten sind. Die Neugotik prägt Teile der Innenausstattung, insbesondere bei Renovierungsarbeiten im 19. Jahrhundert"}, {"kategorie": "", "text": "Der Hochaltar zeigt eine Darstellung des Heiligen Kreuzes und verweist damit auf das Patrozinium der Kirche. Der Hochaltar stammt aus der Barockzeit und ist kunstvoll mit religiösen Motiven verziert"}, {"kategorie": "", "text": "Eine besondere Kostbarkeit ist die Orgel in der Pfarrkirche Grinzing, auf welcher nach örtlicher Überlieferung mehrmals Ludwig van Beethoven sowie auch Franz Schubert musiziert haben sollen."}]'::jsonb, ''),
  ('wiina-heirignkultua', 'Wiina Heirignkultua', '', '', '', '', 'Wiener Heurigenkultur', '[{"kategorie": "allg.", "text": "\"jahrhundertealte Tradition, die sich um den Ausschank und Genuss von jungem Wein – dem sogenannten [[Heurigen]] – in speziellen Weinstuben, den [[Heurigenlokalen]], dreht\""}, {"kategorie": "", "text": "Diese Tradition ist tief in der Wiener Lebensart verankert und verbindet Weinbau, Gastronomie und Geselligkeit auf besondere Weise. Der Begriff à„Heuriger“ bezeichnet sowohl den jungen Wein des aktuellen Jahrgangs als auch die Lokale, in denen dieser ausgeschenkt wird"}, {"kategorie": "", "text": "Die Wurzeln der Heurigenkultur gehen auf eine Verordnung des Kaisers Josef II. im Jahr 1784 zurück, die es den Weinbauern erlaubte, ihre eigenen Weine ohne Zwischenhändler direkt an Gäste zu verkaufen. Dies legte den Grundstein für die Tradition der Heurigen, bei der Weinbauern ihre Produkte in einem gemütlichen, familiären Rahmen anbieten konnten"}, {"kategorie": "", "text": "Die Tradition des Heurigen wurde im Laufe der Jahrhunderte immer stärker in die Wiener Kultur integriert. Besonders in den Außenbezirken Wiens, wie [[Grinzing]], [[Neustift]] am Walde, [[Sievering]], [[Stammersdorf]] und [[Nussdorf]], entstanden zahlreiche Heurigenlokale, die diese Kultur bis heute pflegen"}, {"kategorie": "", "text": "Die Heurigenkultur ist eng mit dem Wiener Weinbau verbunden. Wien ist die einzige Hauptstadt der Welt mit bedeutendem Weinbau innerhalb der Stadtgrenzen. Besonders bekannt sind die Wiener Weine wie der [[Gemischte]] Satz (eine spezielle Wiener Weinsorte), [[Grüner]] Veltliner, [[Riesling]] und [[Zweigelt]]. Der Wein wird oft direkt vom Winzer im Heurigenlokal ausgeschenkt, was die Nähe zwischen Erzeuger und Konsument unterstreicht"}, {"kategorie": "", "text": "Ein weiteres typisches Element der Wiener Heurigenkultur ist die [[Heurigenmusik]], die oft live von Musikgruppen in den Lokalen gespielt wird. Diese Musik ist meist eine Mischung aus Wiener Liedern, Volksmusik und traditioneller Tanzmusik. Sie trägt wesentlich zur geselligen und gemütlichen Atmosphäre bei und ist ein unverzichtbarer Teil der Wiener Lebensart."}]'::jsonb, ''),
  ('pfoakiachn-siivaring', 'Pfoakiachn Siivaring', '', '', '', '', 'Pfarrkirche Sievering', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im Stadtteil [[Sievering]] im 19. Wiener Gemeindebezirk ([[Döbling]]), auch bekannt als \"Pfarrkirche St. Severin\" bzw. \"Sieveringer Pfarrkirche\""}, {"kategorie": "", "text": "Sie ist dem heiligen Severin geweiht und wurde 1733 im barocken Stil neu errichtet"}, {"kategorie": "", "text": "Die Fassade der Kirche ist weiß und von einem schmalen Kirchturm gekrönt, der das Ortsbild von Sievering prägt. Der Hochaltar zeigt eine Darstellung des heiligen Severin, weitere Statuen und Bilder, die das Innere der Kirche schmücken, stammen aus verschiedenen Epochen und zeugen von der langen religiösen Tradition des Ortes"}, {"kategorie": "", "text": "Der heilige Severin, dem die Kirche geweiht ist, war ein frühchristlicher Missionar und Bischof, der im 5. Jahrhundert in Noricum (einem Teil des heutigen Österreichs) wirkte. Er wird als Schutzpatron der Region und als Helfer in schwierigen Zeiten verehrt"}, {"kategorie": "", "text": "Die Kirche liegt im Herzen von [[Sievering]], einem Stadtteil, der für seine idyllische Lage und seine [[Weinbau-Tradition]] bekannt ist. In der Nähe der Pfarrkirche befinden sich mehrere [[Heurigenlokale]] und Weingärten, die dem Viertel seinen ländlichen Charme verleihen."}]'::jsonb, ''),
  ('schleisn-nussduaf', 'Schleisn Nussduaf', '', '', '', '', 'Schleuse Nussdorf', '[{"kategorie": "allg.", "text": "\"Nussdorfer Wehr- und Schleusenanlage\" bzw. \"Nussdorfer Schleuse\" = \"historische und technisch bedeutende Hochwasserschutz- und Schifffahrtsanlage am Eingang des [[Donaukanals]] im Wiener Stadtteil [[Nussdorf]], der im 19. Wiener Gemeindebezirk ([[Döbling]]) liegt"}, {"kategorie": "", "text": "Sie wurde im späten 19. Jahrhundert errichtet, um den Wasserstand im Donaukanal zu regulieren, Hochwasserschutz zu bieten und die Schifffahrt zu ermöglichen. Das Wehr und die Schleusenanlage sind ein prägendes Beispiel für die fortschrittliche Ingenieurskunst der Zeit und zugleich ein architektonisches Werk des berühmten Wiener Architekten Otto Wagner"}, {"kategorie": "", "text": "Die Anlage wurde von Otto Wagner, einem der bedeutendsten Architekten des Wiener Jugendstils, entworfen. Wagner war zu dieser Zeit als Stadtplaner tätig und gestaltete die technische Anlage mit großer architektonischer Sorgfalt, was dem Bauwerk eine ästhetische und kunsthistorische Bedeutung verleiht"}, {"kategorie": "", "text": "Die Wehranlage wird von zwei markanten Jugendstil-Pavillons flankiert, die als Maschinenhäuser dienen und Wagners typischen Stil mit klaren, funktionalen Formen und dekorativen Elementen zeigen"}, {"kategorie": "", "text": "Das Wehr selbst besteht aus einer Reihe von verschließbaren Toren, die das Wasser aus der Donau zurückhalten. Die Schleusenanlage ermöglicht es Schiffen, den Höhenunterschied zwischen der [[Donau]] und dem [[Donaukanal]] zu überwinden"}, {"kategorie": "", "text": "Die Nussdorfer Wehr- und Schleusenanlage ist nicht nur eine bedeutende technische Errungenschaft des späten 19. Jahrhunderts, sondern auch ein wichtiges Baudenkmal des Wiener Jugendstils. Die Anlage wird bis heute genutzt und ist ein wichtiger Bestandteil des Wiener Hochwasserschutzsystems."}]'::jsonb, ''),
  ('nussduafa-wea', 'Nussduafa Wea', '', '', '', '', 'Nussdorfer Wehr', '[{"kategorie": "allg.", "text": "\"Nussdorfer Wehr- und Schleusenanlage\" bzw. \"Nussdorfer Schleuse\" = \"historische und technisch bedeutende Hochwasserschutz- und Schifffahrtsanlage am Eingang des [[Donaukanals]] im Wiener Stadtteil [[Nussdorf]], der im 19. Wiener Gemeindebezirk ([[Döbling]]) liegt"}, {"kategorie": "", "text": "Sie wurde im späten 19. Jahrhundert errichtet, um den Wasserstand im Donaukanal zu regulieren, Hochwasserschutz zu bieten und die Schifffahrt zu ermöglichen. Das Wehr und die Schleusenanlage sind ein prägendes Beispiel für die fortschrittliche Ingenieurskunst der Zeit und zugleich ein architektonisches Werk des berühmten Wiener Architekten Otto Wagner"}, {"kategorie": "", "text": "Die Anlage wurde von Otto Wagner, einem der bedeutendsten Architekten des Wiener Jugendstils, entworfen. Wagner war zu dieser Zeit als Stadtplaner tätig und gestaltete die technische Anlage mit großer architektonischer Sorgfalt, was dem Bauwerk eine ästhetische und kunsthistorische Bedeutung verleiht"}, {"kategorie": "", "text": "Die Wehranlage wird von zwei markanten Jugendstil-Pavillons flankiert, die als Maschinenhäuser dienen und Wagners typischen Stil mit klaren, funktionalen Formen und dekorativen Elementen zeigen"}, {"kategorie": "", "text": "Das Wehr selbst besteht aus einer Reihe von verschließbaren Toren, die das Wasser aus der Donau zurückhalten. Die Schleusenanlage ermöglicht es Schiffen, den Höhenunterschied zwischen der [[Donau]] und dem [[Donaukanal]] zu überwinden"}, {"kategorie": "", "text": "Die Nussdorfer Wehr- und Schleusenanlage ist nicht nur eine bedeutende technische Errungenschaft des späten 19. Jahrhunderts, sondern auch ein wichtiges Baudenkmal des Wiener Jugendstils. Die Anlage wird bis heute genutzt und ist ein wichtiger Bestandteil des Wiener Hochwasserschutzsystems."}]'::jsonb, ''),
  ('pfoakiachn-nussduaf', 'Pfoakiachn Nussduaf', '', '', '', '', 'Pfarrkirche Nussdorf', '[{"kategorie": "", "text": "Die Kirche ist dem heiligen Apostel Thomas geweiht und wurde 1783 während der Reformen von Kaiser [[Joseph]] II. errichtet, als viele kleinere Gemeinden eigene Pfarren erhielten"}, {"kategorie": "", "text": "Die Pfarrkirche St. Thomas ist im typischen Barockstil gehalten und zeichnet sich durch eine schlichte, aber harmonische Gestaltung aus. Die Außenfassade ist weiß, mit einem schlanken Kirchturm, der das Ortsbild von Nussdorf prägt"}, {"kategorie": "", "text": "Der Hochaltar zeigt eine Darstellung des heiligen Thomas Apostel, der als Namenspatron der Kirche gilt. Thomas ist vor allem durch seine Rolle als „ungläubiger Thomas“ bekannt, da er an der Auferstehung Christi zweifelte, bis er die Wunden Jesu selbst sah. Er gilt als Schutzpatron der Architekten, Theologen und Handwerker, und sein Festtag wird am 3. Juli gefeiert"}, {"kategorie": "", "text": "Die Pfarrkirche liegt im historischen Ortskern von Nussdorf, einem Stadtteil, der für seine [[Heurigenkultur]] und [[Weinberge]] bekannt ist. Rund um die Kirche befinden sich traditionelle Heurigenlokale, enge Gassen und historische Häuser, die dem Viertel seinen besonderen Charme verleihen."}]'::jsonb, ''),
  ('nussduafa-laende', 'Nussduafa Lände', '', '', '', '', 'Nussdorfer Lände', '[{"kategorie": "", "text": "Sie erstreckt sich vom [[Nussdorfer]] Wehr, einer markanten Hochwasserschutzanlage, in Richtung Süden bis in die Nähe des [[Franz-Josefs-Kais]] und der Wiener Innenstadt"}, {"kategorie": "", "text": "Historisch diente das Gebiet rund um die Nussdorfer Lände als Hafen- und Umschlagplatz für den Schiffsverkehr auf der Donau und dem Donaukanal. Heute spielt der Schiffsverkehr in diesem Bereich eine geringere Rolle, dafür bietet die Nussdorfer Lände einen schnellen Zugang zum Wiener Zentrum und verbindet den 19. Bezirk mit den inneren Bezirken"}, {"kategorie": "", "text": "Der Donaukanalradweg verläuft ebenfalls entlang der Lände und bietet eine beliebte Route für Radfahrer."}]'::jsonb, ''),
  ('nussduafa-plotz', 'Nussduafa Plotz', '', '', '', '', 'Nussdorfer Platz', '[{"kategorie": "", "text": "Er bildet das historische und gesellschaftliche Zentrum von Nussdorf, einem traditionsreichen Ortsteil, der besonders für seinen Weinbau und seine Heurigenkultur bekannt ist"}, {"kategorie": "", "text": "Der Platz ist von traditionellen Wiener Wohnhäusern, alten Winzerhöfen und Heurigenlokalen umgeben, die den dörflichen Charakter des Stadtteils bewahren. In der Umgebung befinden sich zahlreiche [[Heurigen]], die für ihre gemütliche Atmosphäre und den Ausschank von lokalem Wein bekannt sind"}, {"kategorie": "", "text": "Ein bedeutendes Gebäude am Nussdorfer Platz ist die Pfarrkirche St. Thomas Apostel ([[Pfarrkirche Nussdorf]]), die dem Platz zusätzlich eine religiöse und kulturelle Bedeutung verleiht. Die Kirche ist ein barockes Bauwerk und eine der wichtigsten Sehenswürdigkeiten des Stadtteils."}]'::jsonb, ''),
  ('pfoakiachn-heilignschdodt', 'Pfoakiachn Heilignschdodt', '', '', '', '', 'Pfarrkirche Heiligenstadt', '[{"kategorie": "allg.", "text": "\"eine der ältesten Kirchen Wiens (auch \"Pfarrkirche Sankt Michael\" bzw. \"Heiligenstädter Pfarrkirche\" genannt), die sich im Stadtteil [[Heiligenstadt]] im 19. Wiener Gemeindebezirk ([[Döbling]]) befindet\""}, {"kategorie": "", "text": "Sie ist dem Erzengel Michael geweiht und ein bedeutendes kulturelles und religiöses Wahrzeichen von Heiligenstadt"}, {"kategorie": "", "text": "Die Ursprünge der Pfarrkirche St. Michael gehen auf das 11. Jahrhundert zurück, wobei archäologische Funde darauf hinweisen, dass bereits in der Spätantike und zur Zeit der Römer ein religiöser Ort an dieser Stelle existierte"}, {"kategorie": "", "text": "Die heutige Kirche wurde im 12. Jahrhundert im romanischen Stil errichtet, wobei sie im Laufe der Jahrhunderte mehrfach umgebaut und erweitert wurde"}, {"kategorie": "", "text": "Im 14. und 15. Jahrhundert wurde die Kirche im gotischen Stil umgestaltet, und im Barockzeitalter erhielt sie zusätzliche Verzierungen und Kunstwerke, die ihr heutiges Erscheinungsbild prägen. Die Pfarrkirche wurde als eine der ersten Kirchen Wiens im Mittelalter als Pfarre gegründet und ist damit eine der ältesten Pfarren der Stadt"}, {"kategorie": "", "text": "Die Pfarrkirche Heiligenstadt kombiniert romanische, gotische und barocke Stilelemente, die auf ihre lange Baugeschichte zurückgehen. Das heutige Gebäude ist vorwiegend im gotischen Stil gestaltet, wobei Reste der ursprünglichen romanischen Struktur erhalten geblieben sind"}, {"kategorie": "", "text": "Die Kirche hat einen markanten, quadratischen Kirchturm mit einem spitzen Dach, der das Ortsbild von Heiligenstadt prägt. Die Fassade ist schlicht und verleiht der Kirche ein historisches, zurückhaltendes Aussehen"}, {"kategorie": "", "text": "Das Innere der Kirche ist im barocken Stil gestaltet, mit einem prachtvollen Hochaltar, der eine Statue des Erzengels Michael zeigt. Der Altar ist reich verziert und bildet das Herzstück des Innenraums"}, {"kategorie": "", "text": "Der Erzengel Michael gilt als Schutzpatron der Krieger und wird traditionell als der Anführer der himmlischen Heerscharen dargestellt. Sein Festtag wird am 29. September gefeiert, und er ist die zentrale Figur des Hochaltars in der Kirche."}]'::jsonb, ''),
  ('heilignstaedta-friidhof', 'Heilignstädta Friidhof', '', '', '', '', 'Heiligenstädter Friedhof', '[{"kategorie": "", "text": "Er ist einer der ältesten Friedhöfe in Wien und zeichnet sich durch seine lange Geschichte und die letzte Ruhestätte vieler bedeutender Persönlichkeiten aus"}, {"kategorie": "", "text": "Der Friedhof liegt in der Nähe der Pfarrkirche St. Michael ([[Pfarrkirche]] Heiligenstadt), einer der ältesten Kirchen Wiens, die ebenfalls eng mit der Geschichte Heiligenstadts verbunden ist"}, {"kategorie": "", "text": "Der Friedhof wurde 1873 eingerichtet, liegt in die Wienerwaldlandschaft eingebettet und ist von Weingärten umgeben. Er hat eine Fläche von 20.315 Quadratmetern und verfügt über rund 2.600 Grabstellen"}, {"kategorie": "", "text": "Die Friedhofskapelle, die im typischen Stil der Wiener Friedhofsarchitektur gestaltet ist, bietet einen feierlichen Ort für Trauerfeiern. Viele der Grabstätten stammen aus dem 19. Jahrhundert und sind mit kunstvollen Grabsteinen und Skulpturen versehen, die den Friedhof zu einem interessanten Ort für Kunst- und Geschichtsinteressierte machen"}, {"kategorie": "", "text": "Der Friedhof zeichnet sich durch seine lange Geschichte und die letzte Ruhestätte vieler bedeutender Persönlichkeiten aus, darunter auch Ödön von Horvath (1901–1938), ein bedeutender Dramatiker und Romancier der Zwischenkriegszeit, der besonders für seine Werke wie „Geschichten aus dem Wiener Wald“ und „Jugend ohne Gott“ bekannt ist."}]'::jsonb, ''),
  ('heilignstaedta-park', 'Heilignstädta Park', '', '', '', '', 'Heiligenstädter Park', '[{"kategorie": "allg.", "text": "\"kleine, aber charmante Grünanlage im Wiener Stadtteil [[Heiligenstadt]], der im 19. Wiener Gemeindebezirk ([[Döbling]]) liegt\""}, {"kategorie": "", "text": "Der Heiligenstädter Park befindet sich nahe der [[Heiligenstädter]] Straße und der Pfarrkirche St. Michael ([[Pfarrkirche]] Heiligenstadt). Er liegt in einem Wohngebiet, das durch seine historischen Gebäude und die Nähe zu den [[Wiener]] Weinbergen geprägt ist"}, {"kategorie": "", "text": "Der Gründungsstein des Heiligenstädter Parks aus dem Jahr 1905 ist bis heute erhalten. An beiden Seiten von einer steinernen Bank gefasst trägt er die Inschrift: \"HEILIGENSTÄDTER PARK - Diese Gartenanlage der Stadt Wien wurde an Stelle des ehemaligen Kuglerparkes unter dem BÜRGERMEISTER DR. KARL LUEGER im Jahre 1905 errichtet.\""}]'::jsonb, ''),
  ('wiina-zaunrodbaun', 'Wiina Zaunrodbaun', '', '', '', '', 'Wiener Zahnradbahn', '[{"kategorie": "allg.", "text": "\"historische Bergbahn, die von 1874 bis 1922 in Betrieb war und den Wiener Stadtteil [[Nussdorf]] mit dem beliebten Ausflugsziel [[Kahlenberg]] im 19. Wiener Gemeindebezirk ([[Döbling]]) verband\""}, {"kategorie": "", "text": "Sie war die erste Zahnradbahn Wiens und ermöglichte es den Wienerinnen und Wienern, den Kahlenberg, einen der bekanntesten Aussichtspunkte über Wien und die [[Donau]], bequem zu erreichen"}, {"kategorie": "", "text": "Die Wiener Zahnradbahn wurde am 7. Mai 1874 eröffnet und führte von der Talstation in Nussdorf (nahe dem heutigen [[Nussdorfer]] Platz) hinauf zum Kahlenberg, der sich auf einer Höhe von 484 Metern befindet"}, {"kategorie": "", "text": "Die Wiener Zahnradbahn war eine Bergbahn mit einer Spurweite von 1.000 mm (Meterspur). Ihre Gesamtstrecke betrug etwa 5,5 Kilometer und überwand dabei einen Höhenunterschied von etwa 316 Metern. Aufgrund der steilen Abschnitte wurde die Bahn als Zahnradbahn konzipiert, was ihr den Betrieb auf den steilen Hängen ermöglichte"}, {"kategorie": "", "text": "Die Züge wurden zunächst von Dampflokomotiven gezogen, die den Zahnradantrieb nutzten, um die Steigung zu bewältigen. Später wurde über eine Elektrifizierung der Strecke nachgedacht, doch diese wurde nicht umgesetzt, bevor die Bahn 1922 den Betrieb einstellte."}]'::jsonb, ''),
  ('palaeae-schoenboan', 'Palää Schönboan', '', '', '', '', 'Palais Schönborn', '[{"kategorie": "", "text": "Es wurde im Auftrag von Friedrich Karl von Schönborn, einem bedeutenden Kirchenfürsten und Politiker, von Johann Lucas von Hildebrandt entworfen"}, {"kategorie": "", "text": "Das Palais wurde von 1706 bis 1717 errichtet und diente ursprünglich als Sommerresidenz der Familie Schönborn. Es befand sich damals noch am Stadtrand von Wien, heute jedoch mitten im Zentrum"}, {"kategorie": "", "text": "Zu den bekanntesten Mitgliedern der Familie zählt Friedrich Karl von Schönborn, der ab 1705 Reichsvizekanzler und von 1729 bis zu seinem Tode 1746 Fürstbischof von Würzburg und Bamberg war und anstelle des älteren Lusthauses 1706-1711 nach einem Entwurf Johann Lukas von Hildebrandts (1705/1706) durch dessen Bauführer Franz Jänggl ein Sommerpalais mit Front an der Laudongasse errichten und den Garten neu gestalten ließ"}, {"kategorie": "", "text": "Der Bau spiegelt die luxuriöse Lebensweise des österreichischen Hochadels wider und steht exemplarisch für den Wiener Barockstil. Die Fassade des Gebäudes ist reich an dekorativen Elementen, mit typischen barocken Verzierungen wie Putten und aufwändigen Fensterrahmungen"}, {"kategorie": "", "text": "Der Garten des Palais, der heute ein Park ist, wurde im Stil französischer Barockgärten angelegt und gilt als einer der schönsten Wiener Innenstadtoasen"}, {"kategorie": "", "text": "Heute beherbergt das Palais Schönborn das [[Volkskundemuseum]] Wien, eines der größten und bedeutendsten Museen für Volkskultur in Österreich ."}]'::jsonb, ''),
  ('palaeae-diitrichschdein', 'Palää Diitrichschdein', '', '', '', '', 'Palais Dietrichstein', '[{"kategorie": "allg.", "text": "prachtvolles barockes Bauwerk, das sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) am [[Minoritenplatz]] 3 befindet undseit Beginn des 20. Jahrhunderts als Ministeriumsgebäude sowie vormals auch als Nebenstandort des Bundeskanzleramtes genutzt wurde"}, {"kategorie": "", "text": "1853 kaufte Fürst Franz Josef Dietrichstein das Palais. Die Dietrichsteins waren ein bedeutendes Adelsgeschlecht in der [[Habsburgermonarchie]], das wichtige politische und diplomatische Ämter innehatte"}, {"kategorie": "", "text": "1875 wurde der hintere Trakt demoliert (wohl zur [[Löwelstraße]]), weil man den Platz für den Bau des neuen [[Burgtheaters]] benötigte"}, {"kategorie": "", "text": "Das Palais Dietrichstein zeigt eine prächtige barocke Architektur, die in Wien im 17. und 18. Jahrhundert weit verbreitet war. Der imposante Bau hat eine repräsentative Fassade mit klassischen barocken Elementen wie reichen Stuckverzierungen und symmetrischen Anordnungen"}, {"kategorie": "", "text": "Im Inneren des Palais befinden sich prächtig ausgestattete Räume, die ursprünglich der repräsentativen Nutzung durch den Adel dienten. Zu den herausragenden architektonischen Merkmalen gehören elegante Treppenhäuser, große Empfangsräume und kunstvolle Stuckdecken"}, {"kategorie": "", "text": "Seit 1955 gehört das Gebäude dem österreichischen Staat, seit 1908 wird es von staatlichen Stellen – vom Außenministerium, später auch vom Bundeskanzleramt – genützt."}]'::jsonb, ''),
  ('palaeae-modena', 'Palää Modena', '', '', '', '', 'Palais Modena', '[{"kategorie": "allg.", "text": "ein in den Jahren 1658 bis 1678 fertiggestelltes Palais in der [[Herrengasse]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es befindet sich in der Herrengasse 7 und war ursprünglich ein Renaissance-Gebäude, das durch bauliche Veränderungen zu einem streng klassizistischen Palais wurde"}, {"kategorie": "", "text": "Das Palais wurde im 18. Jahrhundert umgebaut und diente fortan als Residenz für Mitglieder des italienischen Herzogshauses Modena, die enge Verbindungen zu den Habsburgern hatten. Der Name des Palais geht auf diese Familie zurück, genauer auf das Haus Este, das die Herzöge von Modena stellte"}, {"kategorie": "", "text": "Es wurde ursprünglich für Franz III. d’Este, Herzog von Modena und Reggio, errichtet. Franz III. war durch seine Heirat mit Maria Theresias Tochter Maria Beatrix eng mit dem Habsburgerhaus verbunden. Ihre Nachkommen, die Herzöge von Modena, residierten in diesem Palais, wenn sie sich in Wien aufhielten"}, {"kategorie": "", "text": "Heute ist das Palais Modena Sitz des österreichischen Innenministeriums."}]'::jsonb, ''),
  ('heiliges-roemisches-reich', 'Heiliges Römisches Reich', '', '', '', '', 'Heiliges Römisches Reich', '[{"kategorie": "allg.", "text": "\"mittelalterliches und frühneuzeitliches Kaiserreich, das vom 10. Jahrhundert bis zu seiner Auflösung im Jahr 1806 bestand (lateinische Beziechnung: Sacrum Romanum Imperium)\" (in der Folge auch \"Heiliges Römisches Reich deutscher Nation\" bzw. \"römisch-deutsches Reich\" genannt)"}, {"kategorie": "", "text": "Der Name stammt von der Idee der mittelalterlichen Herrscher, dass sie Nachfolger der römischen Kaiser der Antike seien und von Gott auserwählt worden seien, um als oberste Herrscher über die Christenheit zu regieren. Sie sahen sich deshalb über allen anderen Königen Europas"}, {"kategorie": "", "text": "Das Reich umfasste große Teile Mitteleuropas, darunter das heutige Deutschland, Österreich, die Schweiz, Tschechien, Belgien, die Niederlande, sowie Teile Italiens und Frankreichs. Es spielte eine zentrale Rolle in der europäischen Geschichte und entwickelte sich im Laufe seiner Existenz von einem zentralisierten Reich zu einem lockeren Bund von Fürstentümern, Herzogtümern, Bistümern und Städten"}, {"kategorie": "", "text": "Das Heilige Römische Reich ging aus dem Ostfränkischen Reich hervor, einem der Nachfolgereiche des Karolingerreiches von Karl dem Großen. Otto I., König der Ostfranken, wurde im Jahr 962 in Rom von Papst Johannes XII. zum Kaiser gekrönt, was allgemein als Gründungsdatum des Heiligen Römischen Reiches gilt"}, {"kategorie": "", "text": "Die Kaiserkrönung durch den Papst in Rom verlieh dem Reich den Titel \"Heilig\", und der Bezug auf das antike Römische Reich verdeutlichte den Anspruch auf eine universale und göttliche Legitimation der Herrschaft"}, {"kategorie": "", "text": "Die Kurfürsten waren die wichtigsten Fürsten des Reiches, die das exklusive Recht hatten, den Kaiser zu wählen. Zu den Kurfürsten zählten u. a. die Erzbischöfe von Mainz, Trier und Köln sowie weltliche Fürsten wie der König von Böhmen und der Kurfürst von Sachsen"}, {"kategorie": "", "text": "Ab dem 15. Jahrhundert stieg das Haus Habsburg zur dominierenden Macht im Reich auf. Fast durchgehend waren Habsburger auf dem Kaiserthron, was das Reich stark prägte"}, {"kategorie": "", "text": "Im 16. Jahrhundert brachte die Reformation tiefe religiöse und politische Spaltungen ins Reich. Mit der Einführung des Lutheranismus in vielen Teilen des Reiches verlor der Kaiser, der meist katholisch war, an Einfluss, und das Reich zerfiel zunehmend in konfessionell gespaltene Territorien"}, {"kategorie": "", "text": "Der Dreißigjährige Krieg (1618–1648), der als Konflikt zwischen katholischen und protestantischen Fürsten begann, entwickelte sich zu einem umfassenden europäischen Krieg und schwächte das Reich weiter"}, {"kategorie": "", "text": "Das Heilige Römische Reich bestand bis zu seiner Auflösung im Jahr 1806, als Kaiser [[Franz]] II. aufgrund des Drucks von Napoleon Bonaparte und der Gründung des Rheinbundes auf die Kaiserkrone verzichtete. Die Napoleonischen Kriege hatten die Machtstruktur des Reiches endgültig erschüttert und zu dessen Ende geführt"}]'::jsonb, 'Römisch-deutsches Reich'),
  ('roemisch-deutsches-reich', 'Römisch-deutsches Reich', '', '', '', '', 'Römisch-deutsches Reich', '[{"kategorie": "allg.", "text": "siehe [[Heiliges Römisches Reich]]"}]'::jsonb, ''),
  ('palaeae-pallavicini', 'Palää Pallavicini', '', '', '', '', 'Palais Pallavicini', '[{"kategorie": "allg.", "text": "\"prächtiges Stadtpalais im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), das sich am [[Josefsplatz]] 5 befindet, in unmittelbarer Nähe zur [[Wiener]] Hofburg (bekannt auch als \"Palais Fries-Pallavicini\")"}, {"kategorie": "", "text": "Es wurde im späten 18. Jahrhundert im Stil des [[Klassizismus]] erbaut und ist eines der schönsten Beispiele für die klassische Wiener Architektur dieser Zeit"}, {"kategorie": "", "text": "Das Palais wurde zwischen 1783 und 1784 nach den Plänen des berühmten Architekten Ferdinand von Hohenberg errichtet. Ursprünglich für den Grafen Franz Xaver von Fries gebaut, wechselte es später in den Besitz der Familie Pallavicini"}, {"kategorie": "", "text": "Alfonso Pallavicini, ein Nachkomme der reichen und einflussreichen italienischen Adelsfamilie Pallavicini, erwarb das Palais 1842, und es befindet sich seitdem im Familienbesitz. Die Familie Pallavicini stammte ursprünglich aus Genua und gehörte im 19. Jahrhundert zu den führenden Aristokraten in Wien"}, {"kategorie": "", "text": "Das Palais Pallavicini wird auch heute noch von der Familie Pallavicini bewohnt und verwaltet. Die Prunkräume des Palais stehen jedoch auch für exklusive Veranstaltungen zur Verfügung, wie zum Beispiel Hochzeiten, Empfänge oder Konferenzen"}, {"kategorie": "", "text": "Darüber hinaus ist das Palais auch ein beliebter Drehort für Filme und TV-Produktionen, da es durch seine prachtvolle Innenausstattung ein idealer Schauplatz für historische Dramen ist."}]'::jsonb, '')
